// New DG bank. Hand-authored scenarios: first assertion is the validated answer.
// Each assertion has its own rationale after '~'. Rotations balance answer keys.
import {refineDgChallenges} from './rva-dg-challenges.js';
export const RVA_DG_VERSION='rva-dg-2026-11-v1';
const sources=[
  {name:'AAC/RDC — prestataires ATS, AIS, CNS et MET',url:'https://aacrdc.org/website/navigation-aerienne'},
  {name:'OACI — cadre de gestion de la sécurité (Doc 9859)',url:'https://icao.int/SAM/Documents/2017-SSP-GUY/Doc%209859%20SMM%20Third%20edition%20en.pdf'},
];
const sections=['A','B','C','D','E','F'],counts=[9,9,8,7,3,4];
const packs=[];
function pack(n,title,mcq,written){packs.push({n,title,mcq,written});}

pack(1,'Prise de fonction et diagnostic exécutif',`
À votre arrivée comme DG RVA, qui exerce la surveillance réglementaire des services de navigation aérienne ?|L’AAC/RDC~Elle exerce la surveillance du prestataire de navigation aérienne.|La direction de la navigation RVA~Elle organise la prestation et ses contrôles internes.|Le service de sécurité RVA~Il anime le système interne, sans être le régulateur.|Le conseil d’administration RVA~Il supervise l’entreprise, sans délivrer l’approbation réglementaire.
Un défaut touche la chaîne CNS. Quel périmètre votre diagnostic doit-il couvrir en priorité ?|Communication, navigation et surveillance~CNS désigne ces trois fonctions techniques.|Contrôle, normalisation et sûreté~Ces fonctions ne correspondent pas au sigle CNS.|Certification, navigation et sécurité~La certification relève d’une autre fonction institutionnelle.|Communication, navigation et sauvetage~Le sauvetage ne constitue pas le S de CNS.
Votre équipe présente ATS, AIS et MET comme trois prestations RVA identiques. Quelle attribution est exacte selon la page ANS de l’AAC ?|ATS et AIS à la RVA, MET à METTELSAT~La page distingue ces prestataires et leurs domaines.|ATS et MET à la RVA, AIS à METTELSAT~L’information aéronautique n’y est pas attribuée à METTELSAT.|AIS et MET à la RVA, ATS à l’AAC~L’AAC surveille les prestataires, elle n’est pas l’opérateur ATS présenté.|ATS, AIS et MET à la RVA~Cette attribution efface le rôle météorologique de METTELSAT.
Le DG veut mesurer la capacité mobilisable d’un aéroport. Quelle donnée est la plus pertinente ?|Le débit soutenable au goulot contraignant~La capacité utile dépend de la chaîne et de ses contraintes.|Le nombre annuel de passagers transportés~Un volume réalisé ne mesure pas directement la capacité de pointe.|La surface totale du domaine aéroportuaire~La superficie ne révèle pas les contraintes du système.|Le nombre de vols inscrits au programme~La demande programmée ne prouve pas la capacité à la traiter.
Un directeur confond sécurité et sûreté dans son plan. Quelle distinction retenir ?|Accidents involontaires et actes malveillants~La sécurité et la sûreté traitent des familles de menaces distinctes.|Incidents en piste et incidents en aérogare~Le lieu ne définit pas cette distinction.|Risques techniques et risques financiers~Les risques financiers ne définissent pas la sûreté aérienne.|Risques internes et risques externes~Ces deux domaines peuvent concerner des acteurs internes ou externes.
Les interruptions électriques sont rares mais affectent deux systèmes critiques à la fois. Quel concept éclaire ce risque ?|La défaillance de cause commune~Une dépendance partagée peut neutraliser plusieurs équipements.|La défaillance indépendante~Elle suppose précisément l’absence de dépendance commune.|Le risque commercial résiduel~Ce classement ne décrit pas le mécanisme de panne observé.|Le taux moyen d’utilisation~Il mesure une activité et non une dépendance entre défaillances.
Une hausse des passagers masque une baisse des mouvements. Que doit distinguer le DG ?|Trafic passagers et mouvements d’aéronefs~Une évolution du remplissage ou du type d’appareil peut les dissocier.|Trafic facturé et trafic autorisé~Cette distinction ne suffit pas à expliquer les deux volumes physiques.|Trafic de pointe et trafic de nuit~Le constat ne renseigne pas la répartition horaire.|Trafic intérieur et trafic international~Aucune ventilation par destination n’est donnée.
Une restriction d’infrastructure doit être portée à la connaissance des usagers aéronautiques. Quelle chaîne le DG doit-il faire fonctionner ?|Validation technique puis information AIS appropriée~Une donnée vérifiée alimente la chaîne d’information aéronautique compétente.|Validation commerciale puis message aux grands clients~Le canal commercial ne remplace pas l’information aéronautique.|Validation financière puis rapport mensuel au conseil~Ce circuit ne permet pas d’informer les usagers dans le délai utile.|Validation du fournisseur puis communiqué de presse~Le communiqué ne remplace pas le circuit aéronautique applicable.
Votre inventaire recense 95 % d’équipements en service mais ignore leur criticité. Quelle limite affecte ce chiffre ?|Il pondère pareil des fonctions inégales~Un taux global peut masquer l’indisponibilité d’une fonction essentielle.|Il sous-estime nécessairement la capacité~La direction du biais ne peut pas être déduite de ce taux.|Il mesure déjà le service de bout en bout~Un comptage d’actifs ne prouve pas la disponibilité du service.|Il surestime nécessairement les dépenses~Le taux ne permet aucune conclusion sur les coûts.
Durant les dix premiers jours, quel livrable du DG fonde le mieux un plan de cent jours ?|Un diagnostic priorisé avec données vérifiées~Les priorités exécutives doivent partir des risques, capacités et ressources constatés.|Un programme d’achats issu des demandes de sites~Ces demandes doivent être confrontées aux besoins et dépendances.|Un organigramme cible avant les visites de terrain~Les changements de structure ne remplacent pas le diagnostic.|Un objectif de recettes calé sur la meilleure année~Une référence favorable ne décrit pas les contraintes actuelles.
Deux projets sont possibles : extension commerciale ou suppression d’un point unique de panne critique. Quelle méthode de classement convient ?|Filtrer d’abord les contraintes de sécurité~Une option inadmissible en sécurité ne devient pas acceptable par sa rentabilité.|Classer par rendement puis traiter les contraintes~Un classement purement financier peut retenir une solution non admissible.|Classer par délai puis compenser les risques~Un délai court ne rend pas automatiquement le risque maîtrisable.|Classer par financement déjà disponible~La disponibilité des fonds ne suffit pas à établir la priorité.
Un contrat commercial exige une capacité supplémentaire non démontrée. Que doit proposer le DG ?|Un engagement conditionné à la capacité vérifiée~Les engagements doivent correspondre à un service effectivement mobilisable.|Un engagement ferme fondé sur la croissance attendue~Une prévision de demande ne démontre pas la capacité technique.|Une remise compensant tout dépassement futur~Une remise ne résout pas le goulot ni le risque d’exploitation.|Une réservation prioritaire sans étude des autres usagers~Le déplacement de la contrainte ne crée pas de capacité.
Quel objectif de cent jours est le mieux construit pour le recouvrement ?|Réduire les échus ciblés avec responsable et échéance~Il relie une population définie, une action et une mesure vérifiable.|Augmenter le chiffre d’affaires de tous les sites~La facturation ne mesure pas le recouvrement.|Multiplier les réunions avec les débiteurs~Un volume d’activité ne prouve pas l’encaissement.|Atteindre la trésorerie de la meilleure plateforme~La comparaison ignore les différences de taille et de flux.
Le DG envisage une ligne d’activité peu rentable mais indispensable à la continuité. Quelle analyse prépare l’arbitrage ?|Coût de service, obligations et financement~La décision doit expliciter la nécessité du service et sa soutenabilité.|Marge locale après répartition uniforme des frais~Une allocation uniforme peut fausser la contribution évitable.|Rang de la plateforme dans le trafic national~Le rang ne mesure ni la nécessité ni le coût du service.|Valeur historique des actifs concernés~Les dépenses passées ne déterminent pas les options futures.
Un projet dépend d’une alimentation électrique qui sera livrée plus tard. Quel jalon doit commander son calendrier ?|La disponibilité testée du prérequis~La mise en service dépend de la fonction réellement opérationnelle.|La date de réception de l’équipement principal~Recevoir un équipement ne rend pas son environnement exploitable.|La date de signature du contrat de travaux~La signature ne prouve pas la disponibilité du prérequis.|La première facture du fournisseur énergétique~Une facture ne vaut pas essai d’alimentation.
Pour tester une nouvelle recette commerciale, quelle expérience limite le risque d’une généralisation prématurée ?|Un pilote avec critères de décision définis~Les résultats observés déterminent ensuite extension, adaptation ou arrêt.|Une généralisation avec bilan en fin d’année~L’exposition est engagée avant l’apprentissage.|Une annonce de recette avant contractualisation~Une annonce ne vérifie ni la demande ni les coûts.|Une comparaison avec un aéroport de taille différente~Sans ajustement, cette référence n’établit pas la viabilité locale.
Le DG constate des objectifs contradictoires entre maintenance et exploitation. Quelle réponse structure le pilotage ?|Des objectifs communs de service et de risque~Un résultat partagé évite l’optimisation locale au détriment du système.|Un budget identique pour les deux directions~L’égalité des moyens ne règle pas l’incompatibilité des objectifs.|Un classement mensuel du nombre d’interventions~Le volume d’interventions ne mesure pas le service obtenu.|Un rattachement de la maintenance aux achats~Le changement hiérarchique seul ne définit pas les arbitrages.
Quelle hypothèse fragilise le plus un plan fondé sur une hausse de trafic ?|Des recettes prévues sans capacité ni encaissement testés~Le trafic doit pouvoir être servi, facturé et encaissé.|Une ventilation des recettes par type de service~Cette ventilation améliore plutôt l’explicitation du modèle.|Une analyse de sensibilité aux volumes~Elle permet d’évaluer l’exposition à l’incertitude.|Un phasage des dépenses par jalons~Il limite l’engagement avant vérification des prérequis.
Cas fictif : 18 millions facturés, dont 13,5 millions encaissés sur ces mêmes factures. Quel taux de recouvrement ?|75 %~13,5 divisé par 18 donne 0,75.|25 %~C’est la part restant à encaisser.|133,3 %~Ce résultat inverse le rapport demandé.|4,5 %~4,5 est l’écart en millions, pas un taux.
Cas fictif : recettes 24 millions, charges d’exploitation 18 millions. Quelle marge d’exploitation sur recettes ?|25 %~Le résultat de 6 rapporté aux recettes de 24 donne 25 %.|33,3 %~Ce ratio rapporte le résultat aux charges.|75 %~Il s’agit du poids des charges dans les recettes.|6 %~Six est un montant en millions, pas la marge demandée.
La RVA dégage un bénéfice mais sa trésorerie baisse. Quelle analyse lance le DG ?|Un rapprochement résultat-flux et BFR~Créances, investissements et dettes expliquent les décalages de trésorerie.|Un rapprochement chiffre d’affaires-budget~Il ne retrace pas l’ensemble des mouvements de liquidités.|Une comparaison des marges entre sites~Elle renseigne la rentabilité, pas les flux encaissés.|Une réévaluation des immobilisations~Une valeur comptable accrue ne fournit pas de liquidités.
Des créances anciennes sont contestées. Quel montant retenir dans le plan de trésorerie à court terme ?|Les encaissements probables datés~Une prévision de liquidité repose sur les règlements attendus et leur risque.|La totalité des factures émises~La facturation n’assure ni acceptation ni paiement.|La valeur nette comptable des créances~Une estimation comptable ne fixe pas les dates de règlement.|Le plafond de paiement des contrats~Un plafond ne mesure pas les sommes effectivement recouvrables.
Pour comparer deux contrats de maintenance, quel périmètre de coût convient ?|Le coût complet à service comparable~Pièces, support, immobilisation et niveau de service doivent être comparables.|Le seul prix annuel de la prestation~Les exclusions et conséquences des pannes peuvent changer le classement.|Le coût d’achat initial de l’équipement~Il ne décrit pas les coûts futurs des deux offres.|Le total des factures de l’année précédente~Le service et les risques des offres nouvelles peuvent différer.
Cas fictif : coûts fixes 3 millions, contribution de 15 par unité de service. Quel volume couvre les coûts fixes ?|200 000 unités~3 000 000 divisé par 15 donne 200 000.|45 000 unités~Ce volume ne couvre que 675 000 de coûts fixes.|20 000 unités~Une erreur d’échelle réduit le seuil d’un facteur dix.|300 000 unités~Ce volume dépasse le seuil demandé de moitié.
Un fournisseur accorde 10 % de remise contre paiement anticipé. Quelle comparaison précède l’accord ?|Gain net, liquidité et risque de non-livraison~Le rabais doit être comparé au financement et à l’exposition créée.|Montant de la remise et budget d’achat initial~Le budget ne mesure ni le coût financier ni le risque d’exécution.|Prix remisé et valeur historique des stocks~La valeur des stocks ne tranche pas l’opportunité d’un prépaiement.|Remise et moyenne des dépenses des autres sites~Cette comparaison ne mesure pas l’effet sur la trésorerie disponible.
Une dépense de maintenance a été reportée pour améliorer le résultat. Quel diagnostic financier est nécessaire ?|Séparer économie durable et dette de maintenance~Le résultat peut être amélioré au prix d’un risque et de coûts futurs.|Assimiler le report à un gain de productivité~Le même service futur n’est pas démontré à moindre coût.|Réduire le budget suivant du même montant~Cela pérennise une économie dont la soutenabilité reste inconnue.|Reclasser le report en recette exceptionnelle~Un report de dépense n’est pas une recette.
Une indisponibilité critique est signalée pendant une pointe. Quelle première action du DG est adaptée ?|Activer la conduite d’incident prévue~Elle mobilise les responsables habilités, les protections et la coordination.|Demander au conseil de choisir la configuration technique~Le conseil ne remplace pas la chaîne opérationnelle habilitée.|Attendre le diagnostic définitif avant toute protection~Les mesures conservatoires ne doivent pas dépendre de cette attente.|Négocier les pénalités avant de réduire l’exposition~Le traitement contractuel ne sécurise pas le service immédiat.
Un directeur accepte verbalement un risque hors de sa délégation. Comment le DG traite-t-il le dossier ?|Reprendre l’arbitrage au niveau compétent~L’acceptation doit respecter les pouvoirs et les critères de risque applicables.|Régulariser la signature sans réexaminer le risque~La forme ne remplace pas l’évaluation de l’acceptabilité.|Imputer la responsabilité au seul chef de site~Une imputation ne résout ni l’exposition ni le défaut de délégation.|Attendre la prochaine revue annuelle des risques~Le risque reste engagé sans décision valable pendant l’attente.
Les pannes reviennent après remplacement des pièces. Quelle instruction donne le DG ?|Analyser les causes et vérifier l’efficacité~La répétition appelle un traitement causal, au-delà du dépannage.|Augmenter le stock de pièces à l’identique~Cela réduit éventuellement le délai mais ne traite pas la cause.|Remplacer le prestataire avant analyse du défaut~Changer d’acteur ne démontre pas la disparition de la cause.|Clore chaque ticket dès remise sous tension~La remise en marche ne prouve pas une réparation durable.
Quel dispositif rend une délégation d’exploitation utilisable ?|Périmètre, moyens et seuils d’escalade~L’exécutant doit connaître ses pouvoirs, ressources et limites.|Intitulé du poste et ancienneté du titulaire~Ces informations ne définissent pas les décisions autorisées.|Objectif annuel et prime de performance~L’incitation ne précise pas les pouvoirs ni les restrictions.|Validation de toutes les décisions par le DG~Cette centralisation neutralise la délégation annoncée.
Une nouvelle procédure diminue les délais mais change les interfaces de sécurité. Que doit organiser le DG avant déploiement ?|Une gestion du changement documentée~Les risques, interfaces, compétences et essais doivent être examinés.|Une validation par la seule direction commerciale~Le bénéfice commercial ne couvre pas les risques d’interface.|Une expérimentation sans critères d’arrêt~Elle expose le service sans limites d’acceptation définies.|Une revue après un trimestre d’exploitation~Cette revue tardive ne traite pas les risques avant introduction.
Un rapport de disponibilité exclut les pannes de moins d’une heure sans l’indiquer. Que corrige le DG ?|La définition et la traçabilité de l’indicateur~Les exclusions doivent être explicites pour interpréter le service rendu.|Le seuil annuel sans modifier les données~Un objectif différent ne répare pas une définition trompeuse.|Le nom du tableau de bord~L’intitulé ne corrige pas le contenu mesuré.|La périodicité de présentation au conseil~Une fréquence accrue reproduit le même biais.
Des habilitations arrivent à échéance avant le prochain cycle de formation. Quelle réponse du DG est appropriée ?|Adapter le planning aux compétences valides~La continuité doit respecter les exigences de qualification applicables.|Maintenir le planning au titre de l’expérience~L’expérience ne vaut pas automatiquement habilitation valide.|Demander une prolongation interne générale~Le DG ne peut présumer un pouvoir de dérogation réglementaire.|Réduire le contrôle documentaire des équipes~Cela masque le problème sans rendre les personnels habilités.
Le conseil a approuvé une stratégie. Quel rôle appartient au DG ?|La traduire en plans et rendre compte~La direction générale organise l’exécution dans son mandat.|Conduire les délibérations à la place du PCA~La présidence du conseil ne découle pas de l’exécution de la stratégie.|Délivrer les approbations de l’AAC~Le mandat de dirigeant ne confère pas le pouvoir du régulateur.|Transférer la responsabilité de gestion au comité d’audit~Le contrôle ne se substitue pas à la gestion exécutive.
Le DG découvre un conflit d’intérêts dans son équipe d’achat. Quelle mesure immédiate protège la décision ?|Écarter l’influence et tracer le traitement~La déclaration et le traitement effectif protègent l’impartialité de la procédure.|Garder l’évaluateur si son offre préférée est moins chère~Un prix favorable ne neutralise pas le conflit.|Modifier les critères après lecture des offres~Cela compromet l’égalité et la fiabilité de l’évaluation.|Faire voter l’équipe sans consigner le lien~Un vote ne fait pas disparaître une influence non traitée.
Un investissement dépasse votre délégation. Quelle démarche relève du DG ?|Préparer l’arbitrage de l’organe compétent~Le dossier doit expliciter options, risques, financement et recommandation.|Fractionner l’engagement en commandes autonomes~Le fractionnement contourne le seuil au lieu de respecter la compétence.|Signer sous réserve d’une approbation future~L’entreprise peut être engagée avant la décision autorisée.|Transférer la signature au directeur technique~Le transfert ne crée pas un pouvoir absent de la délégation.
Cas fictif : trésorerie faible et panne d’alimentation commune à deux sites. Quelle priorité de DG ?|Sécuriser les services puis financer la réponse~La continuité critique et les mesures de protection structurent les arbitrages.|Régler d’abord toutes les factures par ancienneté~L’ancienneté seule ignore la criticité et l’effet sur le service.|Attendre la recette commerciale de fin de mois~Le risque immédiat ne peut être laissé sans traitement.|Réduire toutes les dépenses dans la même proportion~Une coupe uniforme peut retirer les moyens d’une protection essentielle.
Cas fictif : le tableau annonce zéro incident, des agents signalent une sous-déclaration. Que décide le DG ?|Vérifier les remontées et protéger le signalement~L’absence de déclaration ne prouve pas l’absence d’événement.|Reconduire la prime indexée sur le zéro incident~L’incitation peut renforcer la rétention d’information.|Auditer les seuls événements déjà enregistrés~Le périmètre exclut précisément les événements potentiellement omis.|Demander aux managers une attestation sans recoupement~Une déclaration supplémentaire ne vérifie pas le défaut signalé.
Cas fictif : un directeur promet une reprise avant les essais. Quelle communication valide le DG ?|Un calendrier conditionné aux critères de reprise~Il relie l’information publique aux preuves opérationnelles nécessaires.|Une date ferme assortie d’une réserve générale~La réserve ne démontre pas la faisabilité de la promesse.|Une date calée sur la fin du contrat fournisseur~L’échéance contractuelle ne vaut pas essai concluant.|Une reprise annoncée dès livraison des pièces~La livraison ne prouve ni installation ni fonctionnement sûr.
Cas fictif : le DG reçoit trois diagnostics contradictoires du même incident. Que fait-il ?|Organiser une analyse factuelle contradictoire~Les observations et hypothèses doivent être confrontées sur une base commune.|Retenir le diagnostic du service le plus ancien~L’ancienneté ne constitue pas une preuve de causalité.|Choisir celui qui minimise le coût de réparation~Le coût ne valide pas l’explication technique.|Faire une moyenne des délais annoncés~Une moyenne ne résout pas l’incompatibilité des diagnostics.
`,[
['A','Vous prenez vos fonctions de DG RVA. Décrivez le diagnostic initial permettant de distinguer prestation, contrôle interne et surveillance réglementaire.','Cartographier les services et leurs responsables, les interfaces ATS/AIS/CNS et les dépendances, notamment METTELSAT. Identifier les exigences applicables et les constats de l’AAC sans se substituer au régulateur. Vérifier les données de sécurité, disponibilité, compétences et trésorerie sur le terrain. Prioriser les écarts selon leur criticité et définir responsables, ressources et échéances.','Cartographie des responsabilités','Données vérifiées','Priorisation et responsables'],
['B','Construisez les étapes d’un plan de cent jours du DG RVA sans présumer de nouvelles recettes ni de moyens illimités.','Partir d’un diagnostic de sécurité, continuité, ressources humaines et trésorerie. Définir quelques objectifs mesurables avec situation initiale, responsables et échéances. Chiffrer les ressources et dépendances, traiter les risques urgents, puis séquencer les améliorations. Faire approuver les arbitrages dépassant la délégation et rendre compte des résultats et écarts au conseil.','Diagnostic initial','Objectifs chiffrés et responsables','Ressources et compte rendu'],
['C','Cas fictif : liquidités 1,2 million, encaissements probables 0,9 million, décaissements exigibles 2,6 millions. Calculez le besoin et proposez un plan de DG.','Le solde prévu est négatif de 0,5 million. Valider dates et probabilité des encaissements, établir une prévision glissante et préserver les dépenses critiques. Accélérer les créances recouvrables, négocier les échéances admissibles et étudier un financement autorisé. Affecter les responsables et suivre quotidiennement les flux sensibles sans assimiler factures et liquidités.','Besoin de 0,5 million','Prévision datée','Mesures financées et autorisées'],
['C','Un résultat d’exploitation RVA fictif progresse alors que les créances et les reports de maintenance augmentent. Quelle lecture financière et quelles décisions prenez-vous comme DG ?','Rapprocher résultat et flux encaissés, analyser l’ancienneté et la qualité des créances et le besoin en fonds de roulement. Identifier la maintenance différée, les risques créés et le coût du rattrapage. Distinguer économies durables et reports temporaires. Lancer un recouvrement ciblé et financer un rattrapage priorisé, avec indicateurs communs financiers et opérationnels.','Résultat versus trésorerie','Dette de maintenance','Actions de recouvrement et rattrapage'],
['D','Une alimentation électrique commune perturbe deux fonctions critiques RVA dans ce cas fictif. Décrivez vos premières décisions de DG et les conditions de retour au service.','Activer la conduite d’incident, faire protéger les fonctions exposées et appliquer les procédures de continuité par les personnels habilités. Coordonner les responsables techniques et l’information aéronautique utile. Diagnostiquer la dépendance commune, affecter les moyens, définir les critères d’essais et de reprise. Informer les organes concernés selon leurs compétences et vérifier l’efficacité après rétablissement.','Conduite d’incident et protection','Responsables habilités et coordination','Essais et reprise vérifiée'],
['D','La maintenance RVA fictive multiplie les dépannages mais les pannes se répètent. Organisez une réponse de DG allant au-delà de l’achat de pièces.','Faire analyser l’historique, les modes de défaillance et leurs causes : environnement, installation, compétences ou conception. Sécuriser provisoirement le service, prioriser les actifs critiques, attribuer un responsable et un budget. Définir des actions correctives et mesurer la récurrence, les délais et la disponibilité du service. Clore les actions sur preuve d’efficacité, pas sur facture payée.','Analyse causale','Plan doté de moyens','Preuve d’efficacité'],
['D','Des responsables RVA interprètent différemment leurs pouvoirs pendant une interruption. Comment reconstruisez-vous la délégation comme DG ?','Définir les décisions autorisées par fonction, les ressources et limites, les seuils d’escalade et les suppléances. Faire vérifier la cohérence avec les textes et délégations applicables. Documenter les interfaces, former les équipes et tester le dispositif en exercice. Contrôler les décisions et corriger les écarts, tout en conservant la responsabilité exécutive de pilotage.','Pouvoirs et limites','Escalade et suppléances','Formation et contrôle'],
['E','Le conseil RVA approuve une orientation stratégique sans préciser les modalités. Que préparez-vous comme DG et que réservez-vous au conseil ?','Traduire l’orientation en objectifs, plans, ressources, responsabilités et indicateurs. Identifier les décisions et engagements relevant de la délégation du DG et les arbitrages à soumettre au conseil. Présenter les options et risques avec une recommandation puis exécuter les décisions régulières. Rendre compte des écarts sans confondre direction opérationnelle et présidence du conseil.','Plan d’exécution','Compétences et délégations','Compte rendu au conseil'],
['E','Un responsable d’achat RVA entretient un lien financier avec un candidat fournisseur. Décrivez votre traitement de DG avant de poursuivre l’évaluation.','Faire déclarer et consigner le lien, protéger les pièces et apprécier son incidence selon les règles applicables. Retirer l’intéressé des décisions affectées, organiser une évaluation indépendante et examiner les actes déjà accomplis. Garantir la confidentialité et la traçabilité, saisir les organes compétents si nécessaire. Ne pas présumer la culpabilité ni considérer le prix comme un remède au conflit.','Déclaration et préservation','Retrait et indépendance','Traçabilité et suites compétentes'],
['F','Cas RVA fictif : données de sécurité peu fiables, trésorerie tendue et pression pour annoncer une croissance rapide. Présentez vos trois priorités de DG et votre compte rendu au conseil.','Fiabiliser les alertes et traiter immédiatement les expositions critiques ; établir ensuite un plan de continuité et de trésorerie protégeant les fonctions essentielles. Conditionner les engagements de croissance à la capacité et au financement démontrés. Affecter responsables et échéances, présenter hypothèses, limites et arbitrages au conseil. Rapporter des résultats vérifiables plutôt que des annonces non étayées.','Sécurité et fiabilité des données','Continuité et trésorerie','Croissance conditionnée et compte rendu'],
]);

pack(2,'Exploitation, sécurité et continuité',`
Un système redondant partage le même refroidissement. Que doit vérifier le DG pour apprécier la résilience ?|L’indépendance des défaillances possibles~La redondance matérielle peut être annulée par une dépendance commune.|Le nombre de composants installés~Deux composants ne garantissent pas deux chaînes indépendantes.|La durée de garantie du second système~La garantie ne démontre pas la tenue du service en cas de défaut commun.|Le coût de remplacement du refroidissement~Le coût ne mesure pas l’exposition simultanée des deux chaînes.
Une plateforme n’a connu aucun accident mais ses écarts techniques augmentent. Quelle interprétation relève du DG ?|Le résultat passé ne prouve pas la maîtrise actuelle~Les précurseurs peuvent se dégrader avant qu’un accident survienne.|Le niveau de risque est inchangé jusqu’à un accident~L’absence de dommage ne valide pas l’exposition actuelle.|Les écarts sont compensés par le résultat historique~Un bon historique ne neutralise pas les défaillances présentes.|Le service peut rester à pleine capacité sur cette base~La capacité admissible dépend d’une analyse des conditions actuelles.
Un service ATS utilise des données AIS périmées. Quelle relation doit être traitée ?|Une interface entre prestation et information~La qualité de l’information conditionne le service qui l’utilise.|Une anomalie limitée à l’archivage documentaire~La donnée utilisée peut affecter le service, au-delà de son rangement.|Une question de facturation des prestations~La facturation ne corrige pas la validité de l’information.|Une simple variation du trafic commercial~Le volume de trafic ne détermine pas l’actualité des données.
Une équipe appelle « danger » la probabilité d’un dommage. Quelle correction conceptuelle est exacte ?|Le danger est la source potentielle de dommage~Le risque combine l’appréciation de la probabilité et de la gravité.|Le danger est le coût financier moyen du dommage~Le coût estimé ne définit pas le danger.|Le danger est la seule gravité du dommage~La gravité est une dimension du risque et non la source.|Le danger est le niveau de risque après traitement~Le risque résiduel ne définit pas le danger initial.
Deux mois affichent chacun huit événements, pour 2 000 puis 4 000 mouvements. Quel constat est justifié ?|Le taux par mouvement a diminué de moitié~Le dénominateur double à nombre d’événements constant.|Le risque total a certainement diminué de moitié~La gravité et la nature des événements restent inconnues.|La gravité moyenne des événements est stable~Le comptage ne renseigne pas leur gravité.|La qualité du signalement est nécessairement meilleure~Aucune donnée de complétude des déclarations n’est fournie.
Les équipes confondent plan de continuité et reprise informatique. Quelle distinction doit retenir le DG ?|Le premier couvre le service, la seconde les systèmes~La reprise informatique contribue à une continuité plus large incluant personnes et installations.|Le premier vise les finances, la seconde l’exploitation~La continuité couvre aussi les opérations et ressources humaines.|Le premier intervient après la seconde~Le mode dégradé peut devoir fonctionner avant la restauration informatique.|Le premier relève du conseil, la seconde du DG~La direction organise les deux dans leurs périmètres respectifs.
Le fournisseur mesure la disponibilité d’un serveur, l’exploitation celle du service rendu. Pourquoi les taux diffèrent-ils ?|Les périmètres de mesure ne coïncident pas~Un serveur actif peut participer à une chaîne de service indisponible.|Le taux serveur doit être retenu par principe~La mesure pertinente dépend du service et du périmètre contractuel.|Le taux service mesure nécessairement l’utilisation~Disponibilité et utilisation sont deux notions distinctes.|La différence révèle forcément une fraude~Des définitions différentes suffisent à expliquer un écart sans fraude.
Quel document aide le DG à comprendre la criticité d’un système RVA ?|La cartographie des services et dépendances~Elle relie chaque actif aux fonctions et conséquences de défaillance.|Le registre des valeurs nettes comptables~Un actif amorti peut assurer une fonction essentielle.|Le classement des fournisseurs par dépenses~Le montant acheté ne mesure pas la conséquence d’une panne.|Le relevé des garanties encore valides~La garantie ne définit pas la criticité du service.
Une activité essentielle dépend d’un unique agent qualifié. Quel risque le DG doit-il intégrer ?|Une fragilité de continuité des compétences~L’absence de suppléance qualifiée crée une dépendance individuelle.|Une insuffisance certaine de performance~La compétence unique peut être performante mais peu résiliente.|Un excès de spécialisation des équipements~La dépendance observée porte d’abord sur les personnes.|Un défaut nécessaire de rémunération~Aucune donnée ne permet de conclure sur la rémunération.
Un programme de sécurité propose cinquante actions sans hiérarchie. Comment le DG le rend-il exécutable ?|Prioriser selon risques, dépendances et moyens~Le séquencement doit réduire les expositions majeures avec des responsables identifiés.|Classer par facilité de clôture documentaire~Les actions les plus simples peuvent laisser les risques majeurs ouverts.|Financer chaque action à parts égales~Les coûts et effets attendus ne sont pas égaux.|Suivre le nombre total d’actions closes~Un volume de clôtures ne mesure pas la réduction du risque.
Une amélioration de capacité suppose une coordination avec un autre prestataire. Quel engagement convient au DG ?|Un accord d’interface testé avant montée en charge~Les responsabilités et conditions de fonctionnement doivent être vérifiées ensemble.|Une consigne interne RVA diffusée aux seuls sites~Une consigne unilatérale ne règle pas la dépendance externe.|Une réserve budgétaire pour les retards éventuels~Le financement d’un retard ne garantit pas la coordination.|Une clause de pénalité en remplacement des essais~La pénalité ne démontre pas le fonctionnement de l’interface.
Une plateforme peut accroître son trafic en repoussant sa maintenance. Quelle décision doit être étayée ?|Comparer la capacité soutenable sous contraintes~Le gain immédiat doit intégrer l’état des actifs et les risques futurs.|Retenir le scénario offrant le plus de mouvements~Le volume maximal n’établit pas la soutenabilité.|Aligner la maintenance sur le programme commercial~Le programme commercial ne détermine pas seul les limites techniques.|Compter la maintenance reportée comme réserve de capacité~Un report n’est pas une ressource durable de capacité.
Un fournisseur propose une technologie nouvelle sans support local. Quelle condition est déterminante pour la stratégie du DG ?|La capacité à maintenir le service sur sa durée~Compétences, pièces, support et réversibilité conditionnent la viabilité.|Le niveau de performance annoncé en démonstration~Une démonstration ne couvre pas les conditions de soutien en exploitation.|La part de marché mondiale de la technologie~Une adoption large ne garantit pas le support dans le contexte local.|L’économie sur la première année d’entretien~Le cycle de vie dépasse l’horizon de la remise initiale.
Pour une extension de service, quand le DG doit-il examiner les besoins de formation ?|Pendant la conception du changement~Le calendrier et les ressources de qualification conditionnent la mise en service.|Après réception technique des équipements~Ce moment peut laisser le service sans personnel prêt.|Après confirmation du trafic supplémentaire~L’exposition peut commencer avant la disponibilité des compétences.|Pendant le premier bilan annuel du nouveau service~Le contrôle arrive trop tard pour préparer le démarrage.
Le DG doit choisir entre deux solutions offrant le même niveau de sécurité admissible. Quel critère affine le choix ?|Le coût complet et la robustesse d’exploitation~Après admissibilité, la comparaison porte sur soutenabilité et service.|Le seul coût des travaux de démarrage~Il omet les charges d’entretien et de soutien.|Le nombre de fonctionnalités du catalogue~Des fonctions supplémentaires n’améliorent pas nécessairement le besoin réel.|La durée de vie maximale annoncée~La durée annoncée doit être reliée aux conditions d’usage et de maintenance.
Quel objectif stratégique rend la résilience mesurable ?|Rétablir les fonctions prioritaires dans un délai testé~Il relie criticité, niveau de service et preuve d’exercice.|Maintenir un stock identique sur toutes les plateformes~L’uniformité ignore les besoins, délais et dépendances locaux.|Réduire les dépenses de secours chaque année~La baisse des coûts ne prouve pas le maintien des capacités.|Signer un contrat avec un second fournisseur~Un contrat ne prouve pas qu’une bascule est réalisable.
Le trafic croît, les files s’allongent seulement à certaines heures. Quel investissement doit être étudié en premier ?|Celui traitant le goulot des périodes contraintes~L’analyse horaire évite de surdimensionner des segments non limitants.|Une augmentation uniforme de toutes les capacités~Elle peut engager des dépenses sans réduire le goulot réel.|L’ouvrage ayant le plus faible coût unitaire~Un faible coût ne démontre pas l’effet sur le système.|Le projet le plus avancé administrativement~La maturité du dossier ne prouve pas sa priorité opérationnelle.
Quelle hypothèse doit figurer dans un scénario de continuité réaliste ?|L’indisponibilité possible de ressources communes~Une crise peut toucher simultanément communications, énergie et accès.|La disponibilité permanente des responsables titulaires~Cette hypothèse exclut une vulnérabilité importante.|La priorité automatique donnée par tous les fournisseurs~Cette priorité doit être contractualisée et vérifiée.|La restauration complète avant toute activité minimale~Un mode dégradé peut être nécessaire avant la reprise complète.
Cas fictif : un service prévu 720 heures subit 9 heures d’arrêt non exclues. Quelle disponibilité ?|98,75 %~711 divisé par 720 donne 98,75 %.|1,25 %~Ce ratio mesure l’indisponibilité.|99,25 %~Ce taux ne correspond pas à neuf heures sur 720.|97,5 %~Ce taux correspondrait à dix-huit heures d’arrêt.
Cas fictif : 360 heures de fonctionnement entre six pannes distinctes. Quel temps moyen entre pannes sur cette base ?|60 heures~360 heures divisées par six pannes donnent 60 heures.|6 heures~Le nombre de pannes est confondu avec une durée.|120 heures~Ce calcul ne retientrait que trois pannes.|2 160 heures~La multiplication ne donne pas la moyenne demandée.
Un prestataire réclame un forfait moins cher mais exclut les pièces critiques. Quelle comparaison financière demande le DG ?|Réintégrer les exclusions et délais au coût complet~Le prix apparent doit être ajusté au même service et aux risques d’arrêt.|Comparer les forfaits annuels tels qu’affichés~Les périmètres différents rendent le classement trompeur.|Retenir l’offre à garantie la plus longue~La garantie ne couvre pas nécessairement les pièces exclues.|Aligner le budget sur le forfait le plus bas~Le budget ne règle pas les besoins non couverts.
Cas fictif : stock critique de 240 unités, consommation stable de 40 unités par mois. Quelle couverture sans réapprovisionnement ?|6 mois~240 divisé par 40 donne six mois.|4 mois~Cette durée ne correspond pas au stock et à la consommation donnés.|10 mois~Ce résultat surestime la couverture disponible.|9 600 mois~Le produit stock-consommation n’est pas une couverture.
Un stock de sécurité est calculé sans délai de livraison. Quel risque financier et opérationnel en découle ?|Un niveau de stock mal adapté au réapprovisionnement~La protection doit tenir compte du délai et de l’incertitude.|Une valorisation comptable forcément incorrecte~Le niveau de couverture ne prouve pas une erreur de valorisation.|Une baisse certaine du besoin en fonds de roulement~Le stock peut être excessif ou insuffisant ; le sens n’est pas établi.|Une disparition du risque de rupture~Un stock sans délai de référence ne garantit aucune protection.
Cas fictif : un arrêt coûte 12 000 par heure ; une mesure évite 15 heures par an pour 90 000 annuels. Quel gain net annuel, hors autres effets ?|90 000~180 000 de coût évité moins 90 000 de mesure donnent 90 000.|180 000~C’est le coût évité avant financement de la mesure.|270 000~Ce calcul additionne coût évité et dépense.|6 000~Ce montant ne correspond pas au gain annuel demandé.
Un contrat à bas prix transfère au client le financement d’une grande réserve de pièces. Quel poste doit être comparé ?|Le coût de possession des stocks~L’immobilisation, l’obsolescence et le stockage changent l’économie du contrat.|La seule remise sur la prestation~Elle omet les ressources immobilisées dans la réserve.|La valeur brute des immobilisations~La réserve de pièces n’est pas équivalente au parc d’immobilisations.|Le nombre de lignes de la commande~Il ne mesure pas le coût supporté sur la durée.
Le DG veut budgéter une redondance. Quelle justification est recevable ?|Une réduction de risque et une continuité démontrées~La valeur peut venir de la protection du service, sans recette commerciale directe.|Une hausse certaine du chiffre d’affaires~Une redondance n’implique pas automatiquement une demande nouvelle.|Une baisse automatique du coût d’entretien~Deux chaînes peuvent au contraire augmenter les charges d’entretien.|Un amortissement comptable qui finance l’achat~L’amortissement est une charge comptable, pas un encaissement.
Un budget de continuité ne couvre que les achats de secours. Quel complément est nécessaire pour apprécier sa soutenabilité ?|Les coûts récurrents de maintien en condition~Essais, entretien, compétences et support consomment des ressources sur la durée.|La seule valeur de revente du matériel principal~Elle ne finance pas le fonctionnement courant du secours.|Le montant des primes annuelles des commerciaux~Il ne décrit pas les moyens de maintien du dispositif.|Le total des garanties contractuelles obtenues~Une garantie ne couvre pas nécessairement essais, personnel et exploitation.
Une alerte technique justifie un mode dégradé prévu. Quel rôle joue le DG ?|Mobiliser la chaîne habilitée et ses moyens~Le DG organise la réponse sans remplacer les opérateurs techniques compétents.|Choisir lui-même les paramètres de contrôle aérien~Le pilotage exécutif ne confère pas l’habilitation technique correspondante.|Faire voter le mode dégradé par le comité d’audit~Le comité n’est pas la chaîne opérationnelle de l’incident.|Laisser le fournisseur arbitrer l’acceptabilité du risque~Le fournisseur ne reçoit pas seul l’autorité d’acceptation du prestataire.
Un exercice de secours réussit hors pointe avec la moitié des effectifs. Que conclut le DG ?|La preuve reste limitée au scénario testé~Les conditions de pointe et les autres scénarios restent à évaluer.|Le plan est validé pour toute charge de trafic~Une extrapolation générale n’est pas démontrée.|Le nombre d’agents peut être réduit de moitié~La réussite du scénario ne suffit pas à fixer les effectifs permanents.|Le risque résiduel est désormais nul~Un essai réussi n’élimine pas tous les modes de défaillance.
Une équipe ferme une action après formation des agents. Quelle preuve supplémentaire peut être nécessaire ?|La compétence et l’effet sur le risque ciblé~La présence à la formation ne prouve pas l’application efficace.|La facture acquittée de l’organisme formateur~Elle prouve une transaction et non l’efficacité de l’action.|Le nombre d’heures inscrites au programme~Un volume d’enseignement ne démontre pas la maîtrise.|La diffusion du support à tous les sites~La diffusion n’établit ni compréhension ni comportement effectif.
Le DG découvre une configuration différente de la documentation approuvée. Quelle réponse est adaptée ?|Évaluer l’écart et contrôler la configuration~Il faut comprendre l’effet réel avant régularisation ou retour maîtrisé.|Réécrire la documentation d’après l’installation~Aligner les papiers ne démontre pas l’acceptabilité de la configuration.|Restaurer immédiatement toute ancienne version~Un retour non évalué peut créer d’autres risques.|Reporter l’écart au prochain renouvellement du contrat~L’exposition présente n’est pas traitée par cette attente.
Un incident implique exploitation et maintenance ; chacun renvoie la responsabilité. Que fixe le DG ?|Un responsable de traitement et une analyse commune~La responsabilité de coordination évite la rupture entre métiers.|Deux clôtures séparées de l’incident~Elles peuvent laisser les interfaces causales non traitées.|Une répartition égale du coût entre directions~Une clé de coût ne résout pas la cause ni le service.|Une clôture unique par le fournisseur~Le fournisseur ne couvre pas à lui seul toutes les responsabilités internes.
Quel critère de reprise après panne est le plus solide pour le DG ?|Des essais concluants selon des critères définis~Le retour au service repose sur des preuves et validations compétentes.|Le rétablissement de l’affichage de supervision~Un écran normal ne prouve pas toute la chaîne de service.|La déclaration commerciale du fournisseur~Elle ne remplace pas les essais et acceptations requis.|L’expiration de la durée maximale annoncée~Une échéance dépassée ne rend pas la reprise acceptable.
Une remontée d’événement met en cause un cadre performant. Quelle réponse préserve une culture juste ?|Examiner les faits selon une procédure équitable~La protection du signalement n’interdit pas le traitement proportionné des fautes.|Garantir l’absence de suite dans toutes les situations~L’immunité absolue ne distingue pas erreur, négligence ou acte délibéré.|Sanctionner d’abord pour montrer l’exigence~Une sanction préalable peut décourager les signalements et ignorer les faits.|Confier l’examen au seul cadre mis en cause~L’indépendance de l’analyse serait compromise.
L’AAC formule un constat exigeant une réponse du prestataire. Quel rôle du DG RVA est attendu ?|Faire exécuter un plan correctif avec preuves~Le prestataire traite l’écart et répond selon la procédure applicable.|Demander au PCA de réaliser la correction technique~La présidence du conseil ne remplace pas les responsables d’exécution.|Clore le constat après inscription au budget~Un financement prévu ne démontre pas la correction.|Transformer le constat en réserve commerciale~Le traitement contractuel ne répond pas à l’écart réglementaire.
Un risque dépasse le pouvoir délégué au DG. Comment prépare-t-il l’escalade ?|Mesures conservatoires et dossier d’arbitrage~L’escalade doit être documentée et accompagnée d’une protection immédiate appropriée.|Transfert intégral de l’exploitation au conseil~Le conseil ne devient pas l’équipe de conduite opérationnelle.|Acceptation provisoire par simple courriel interne~Un courriel ne crée pas la compétence nécessaire.|Suspension de toute information jusqu’au diagnostic final~Les autorités de décision ont besoin d’une information utile à temps.
Cas fictif : panne CNS et données d’état contradictoires. Quelle action du DG vient en premier ?|Sécuriser le service et vérifier l’état réel~La protection et la confirmation de situation précèdent les engagements de reprise.|Diffuser le taux de disponibilité du mois précédent~Le résultat passé ne décrit pas l’incident en cours.|Confirmer la version la moins perturbante pour le trafic~L’impact commercial ne détermine pas la vérité technique.|Annoncer la réparation dès départ des techniciens~Le déplacement d’une équipe ne prouve pas la remise en service.
Cas fictif : une seule équipe peut intervenir sur deux actifs, dont un à défaut dangereux immédiat. Quel principe de DG s’applique ?|Priorité à l’exposition critique actuelle~La gravité, l’urgence et les protections disponibles structurent l’allocation.|Priorité à l’actif ayant la plus forte valeur comptable~La valeur comptable ne mesure pas le danger immédiat.|Priorité au site qui génère le plus de recettes~La contribution commerciale ne neutralise pas le risque critique.|Priorité au premier ticket enregistré~L’ordre chronologique seul ignore la criticité.
Cas fictif : fournisseur injoignable, incident hors horaires, suppléance non désignée. Quelle faille de continuité faut-il traiter ?|L’organisation de l’astreinte et des escalades~La réponse dépend de contacts, pouvoirs et suppléances effectivement disponibles.|Le seul montant des pénalités du contrat~Des pénalités ne mettent pas une équipe compétente à disposition.|L’amortissement trop rapide des équipements~Ce choix comptable ne décrit pas la faille organisationnelle.|La présentation annuelle du tableau de bord~Le calendrier du rapport ne remplace pas le dispositif d’astreinte.
Cas fictif : un secours fonctionne mais utilise le réseau touché par la panne principale. Que décide le DG ?|Réexaminer la dépendance avant de valider le secours~Le secours reste exposé au même mode de défaillance.|Valider le secours sur son test individuel~Un test isolé ne prouve pas son indépendance en crise.|Augmenter la fréquence des rapports de disponibilité~Le suivi ne supprime pas la dépendance technique.|Considérer le second fournisseur comme garantie suffisante~Deux fournisseurs peuvent utiliser la même infrastructure commune.
`,[
['A','Expliquez au comité de direction RVA la différence entre disponibilité d’un équipement, disponibilité d’un service et résilience.','La disponibilité d’un équipement mesure son aptitude sur un périmètre défini ; le service dépend de toute la chaîne, des équipes et des interfaces. La résilience ajoute la capacité à absorber une perturbation et restaurer les fonctions prioritaires. Cartographier les dépendances, notamment les causes communes, et vérifier la continuité par essais représentatifs plutôt que déduire le service d’un compteur matériel.','Trois notions distinguées','Chaîne et dépendances','Essais représentatifs'],
['B','Une croissance fictive du trafic exige de modifier simultanément procédures et équipements RVA. Présentez votre méthode de DG avant autorisation de mise en service.','Définir le besoin et les limites, analyser les risques et interfaces avec les métiers et intervenants concernés. Vérifier les ressources, compétences, documents et exigences applicables. Phaser le changement, prévoir un mode de retour et des critères d’essais et d’arrêt. Obtenir les validations compétentes puis décider dans la délégation du DG, avec suivi renforcé après démarrage.','Gestion du changement','Prérequis et validations','Essais et retour maîtrisé'],
['C','Cas fictif : 600 heures de service prévues, 12 heures d’arrêt et 30 heures de maintenance explicitement incluses dans les 600. Calculez la disponibilité si les 12 et 30 heures sont disjointes et toutes comptées indisponibles.','Le temps indisponible total est de 42 heures ; le temps disponible de 558 heures. La disponibilité vaut 558/600, soit 93 %. Documenter les exclusions et chevauchements pour éviter un double comptage. Distinguer ensuite l’effet des arrêts planifiés et non planifiés sans changer silencieusement le périmètre de mesure présenté au DG et au conseil.','42 heures indisponibles','Disponibilité de 93 %','Périmètre et double comptage'],
['C','Deux offres fictives de maintenance RVA affichent 0,8 et 1 million par an. La première exclut 0,35 million de pièces probables, la seconde les inclut. Comparez et précisez vos réserves de DG.','À hypothèses identiques, le coût attendu est de 1,15 million pour la première contre 1 million pour la seconde, soit 0,15 million d’écart. Vérifier le périmètre, les plafonds, délais, garanties et probabilité des pièces. Comparer le service, l’immobilisation et les coûts complets sur la même période avant choix, selon les règles d’achat applicables.','Comparaison 1,15 contre 1 million','Écart de 0,15 million','Périmètres et risques comparables'],
['D','Un essai de secours RVA fictif réussit sans charge réelle. Que devez-vous demander comme DG avant de déclarer le dispositif opérationnel ?','Identifier les fonctions prioritaires et les charges représentatives, les dépendances communes et les conditions d’indisponibilité. Organiser des essais maîtrisés avec équipes, astreinte et interfaces réelles ou simulées de façon pertinente. Fixer critères de réussite, limites et reprise. Documenter les résultats, traiter les écarts et revalider sans exposer le service à un essai non maîtrisé.','Scénarios représentatifs','Dépendances et critères','Écarts et validation'],
['D','Un incident RVA fictif a été réparé mais sa cause reste inconnue. Organisez la suite de l’action exécutive sans prétendre qu’un redémarrage clôt le problème.','Maintenir les protections justifiées et préserver les données. Confier une analyse causale aux métiers compétents, recouper les observations et examiner les actifs similaires. Définir actions, responsables, moyens et échéances. Valider la reprise selon critères techniques applicables et suivre la récurrence. Ne clôturer le traitement du risque qu’avec une preuve proportionnée de son efficacité.','Protection et données','Analyse causale multisites','Preuve d’efficacité'],
['D','Les agents RVA fictifs signalent fatigue et indisponibilité de suppléants qualifiés. Quelles décisions relèvent du DG ?','Évaluer la charge, les horaires et les qualifications avec les responsables compétents. Adapter le planning et si nécessaire le niveau de service aux ressources habilitées ; traiter les alertes et organiser repos, suppléance et formation. Définir un plan d’effectifs soutenable, chiffré et suivi. Ne pas remplacer une exigence de qualification par une simple note de service.','Charge et fatigue','Service compatible avec qualifications','Suppléance et moyens'],
['E','Un signalement de sécurité RVA met en cause une personne proche de la direction. Comment garantissez-vous une analyse utile et équitable comme DG ?','Protéger le signalant contre les représailles, préserver les pièces et prévenir les conflits d’intérêts dans l’examen. Distinguer erreur, défaut de système et conduite éventuellement fautive selon les règles applicables, sans immunité absolue ni sanction préalable. Faire analyser les faits par des personnes compétentes et indépendantes, traiter les causes et communiquer les suites avec confidentialité proportionnée.','Protection et indépendance','Analyse équitable','Actions et confidentialité'],
['E','L’AAC adresse dans ce cas fictif un constat à la RVA avec une échéance de réponse. Décrivez votre organisation de DG.','Vérifier le constat et les exigences, désigner un responsable et mettre en place les mesures conservatoires nécessaires. Préparer un plan correctif avec causes, actions, financement, délais et preuves. Coordonner une réponse fidèle avec les services compétents et informer le conseil des risques et arbitrages utiles. Suivre la réalisation et les échanges de validation sans prétendre clore soi-même l’acte du régulateur.','Responsable et mesures conservatoires','Plan et preuves','Réponse au régulateur et suivi'],
['F','Cas fictif : panne de communication, fatigue d’une équipe et pression pour maintenir la pointe. Comment dirigez-vous la réponse RVA ?','Activer la conduite d’incident et faire évaluer les capacités sûres par les responsables habilités. Appliquer les protections et modes dégradés pertinents, ajuster le service aux moyens réellement disponibles, organiser les renforts qualifiés et l’information coordonnée. Affecter les ressources de réparation et fixer les conditions de reprise. Informer les instances concernées puis analyser ensemble défaillance technique et fatigue.','Capacité sûre et chaîne habilitée','Moyens et information','Conditions de reprise et retour d’expérience'],
]);

pack(3,'Finances, recettes et performance',`
Quel rapprochement permet au DG de contrôler la complétude des recettes de service RVA ?|Prestations réalisées, tarifs applicables et factures~Il permet de rechercher les services rendus mais omis ou mal tarifés.|Factures émises et chiffre d’affaires comptable~Ces données peuvent concorder tout en omettant les mêmes prestations.|Encaissements bancaires et solde de trésorerie~Ce rapprochement ne révèle pas les prestations jamais facturées.|Budget de recettes et résultat d’exploitation~Le budget n’est pas la preuve des services effectivement réalisés.
Une plateforme est déficitaire après répartition des frais du siège. Quelle donnée manque avant décision de fermeture ?|Ses coûts évitables et les effets sur le réseau~Une perte allouée ne mesure pas l’économie réelle d’un arrêt.|La moyenne des charges allouées des autres sites~Elle reproduit une allocation sans identifier l’effet de fermeture.|La valeur d’origine de ses bâtiments~Un coût passé ne détermine pas les économies futures.|Le seul nombre de salariés permanents~L’effectif ne couvre pas les obligations et coûts du réseau.
Le délai de facturation s’allonge mais les clients paient aussi vite après émission. Quel indicateur se dégrade d’abord ?|Le délai du service au règlement~Un retard d’émission décale la conversion du service en liquidité.|Le délai entre facture et règlement~L’énoncé précise que ce délai reste stable.|La marge unitaire du service~Un délai n’implique pas à lui seul une variation de marge.|La capacité physique de la plateforme~Le constat porte sur le cycle de recettes et non sur le débit physique.
Le DG compare recettes aéronautiques et commerciales. Quelle précaution est nécessaire ?|Distinguer bases de calcul et inducteurs~Les volumes, contrats et règles tarifaires ne sont pas nécessairement identiques.|Appliquer un prix moyen unique à tout le trafic~Un prix unique masque la diversité des services et contrats.|Classer toute recette encaissée comme commerciale~L’encaissement ne définit pas la nature de la recette.|Assimiler loyers facturés et redevances de navigation~Ces recettes correspondent à des objets différents.
Un actif totalement amorti assure une fonction critique. Quelle conclusion convient au DG ?|Sa valeur comptable ne mesure pas sa criticité~Un actif de valeur nette nulle peut rester indispensable au service.|Il doit être remplacé dès la clôture~L’amortissement terminé ne prouve pas l’inaptitude technique.|Son entretien n’a plus d’intérêt économique~L’utilité du service peut justifier l’entretien.|Son arrêt ne crée plus de perte~Le coût de panne dépasse la valeur inscrite au bilan.
Une direction annonce une hausse des recettes de 15 % avec inflation et variation de trafic. Que doit isoler le DG ?|Les effets volume, tarif et composition~La variation globale peut provenir d’inducteurs différents.|La seule hausse du solde bancaire~Le solde dépend aussi des dépenses et des financements.|Le nombre de factures supplémentaires~La taille et la nature des factures peuvent changer.|La moyenne des budgets des sites~Un budget n’explique pas la variation réalisée.
Pourquoi suivre séparément commandes, services reçus et paiements ?|Pour voir engagements, charges et liquidités~Ces étapes exposent des obligations et flux à des moments différents.|Pour attribuer trois fois la même dépense~Les vues distinctes ne doivent pas être additionnées comme trois coûts.|Pour assimiler réception et encaissement~La réception d’un achat ne crée pas une recette.|Pour remplacer la comptabilité par les commandes~Le suivi des engagements complète la comptabilité sans la remplacer.
Des recettes augmentent tandis que les échus augmentent plus vite. Quel risque le DG doit-il examiner ?|La conversion des ventes en liquidités~La croissance facturée peut masquer une dégradation du recouvrement.|Une baisse certaine du volume de trafic~Les données ne démontrent pas une baisse du volume.|Une sous-évaluation certaine des tarifs~L’évolution des créances ne suffit pas à établir le niveau des prix.|Une surcapacité technique certaine~Aucune donnée de capacité n’est fournie.
Un tableau présente le coût par passager sans les mouvements ni le mix de services. Quelle limite faut-il signaler ?|Le dénominateur peut mal représenter les coûts~Tous les coûts RVA ne varient pas avec le seul nombre de passagers.|Le coût par passager doit toujours remplacer les autres ratios~Un ratio unique ne couvre pas tous les inducteurs de service.|Le ratio révèle directement la productivité de chaque métier~Il agrège des fonctions et coûts hétérogènes.|Le ratio est nécessairement faux comptablement~Un ratio exact peut rester insuffisant pour décider.
Le DG veut augmenter les recettes sans présumer d’un pouvoir tarifaire unilatéral. Quelle première démarche est la plus robuste ?|Sécuriser la facturation des prestations dues~La complétude et l’exactitude améliorent les recettes dans le cadre applicable.|Appliquer une majoration générale dès le mois suivant~Les compétences et procédures tarifaires doivent être vérifiées.|Comptabiliser une hausse de trafic non contractualisée~Une hypothèse n’est pas une recette réalisée.|Transformer les créances contestées en nouvelles factures~Cela ne résout ni leur fondement ni leur recouvrabilité.
Un objectif commercial favorise les volumes mais ignore le coût des heures supplémentaires. Quel ajustement propose le DG ?|Piloter une contribution à service comparable~Le gain doit intégrer les ressources et contraintes nécessaires.|Récompenser le trafic supplémentaire sans autre critère~Le volume seul peut dégrader marge et service.|Limiter la performance au chiffre d’affaires facturé~Le coût et l’encaissement restent absents.|Remplacer le coût réel par le budget initial~Le budget ne mesure pas les moyens effectivement consommés.
Une créance publique importante n’a pas de date de règlement confirmée. Comment l’intégrer au plan de redressement ?|En scénarios datés avec solution de repli~L’incertitude de paiement doit apparaître dans le financement du plan.|Comme encaissement certain à la prochaine clôture~La clôture comptable ne fixe pas l’échéance réelle de règlement.|Comme réduction automatique des dépenses à payer~Une créance ne compense pas toute dette sans mécanisme valable.|Comme financement permanent de la maintenance~Une ressource incertaine ne garantit pas les dépenses critiques.
Deux investissements ont un rendement voisin, mais un seul supprime un risque de rupture essentiel. Que présente le DG ?|Une comparaison intégrant risque et continuité~Le rendement ne couvre pas toute la valeur du projet critique.|Un classement par rendement arrondi au pourcent~L’arrondi peut masquer les enjeux opérationnels déterminants.|Un classement par montant déjà dépensé~Le coût irrécupérable ne doit pas commander l’avenir.|Une préférence pour le plus grand budget~La taille de l’investissement ne démontre pas son utilité.
Une forte croissance impose de nouvelles dépenses avant les encaissements. Quel besoin doit être planifié ?|Le financement du cycle d’exploitation~La croissance peut consommer du fonds de roulement avant de produire du cash.|La seule charge annuelle d’amortissement~Elle ne mesure pas les avances et décaissements du cycle.|Le dividende maximal théorique~Il ne couvre pas le décalage des flux d’exploitation.|La valeur nette des actifs disponibles~Une valeur de bilan n’est pas automatiquement une liquidité mobilisable.
Pour suivre un plan de recouvrement, quel objectif est le plus exploitable ?|Des encaissements datés par débiteur~Il permet d’attribuer l’action et d’en vérifier le résultat.|Un nombre minimal de lettres de relance~Il mesure l’activité mais pas les règlements obtenus.|Une hausse du chiffre d’affaires émis~Elle peut augmenter le stock de créances.|Un budget de déplacement totalement consommé~La consommation de moyens ne prouve pas l’efficacité du recouvrement.
Le DG examine une concession commerciale avec minimum garanti. Quelle analyse évite une recette seulement apparente ?|Solvabilité, conditions et coûts supportés~Le minimum annoncé doit être recouvrable et comparé aux charges et obligations.|Montant facial du minimum garanti~Il omet la capacité de paiement et les contreparties.|Surface totale inscrite au contrat~La superficie ne détermine pas le flux net disponible.|Durée maximale proposée par l’occupant~Une longue durée peut accroître la dépendance sans garantir le paiement.
Un projet est rentable en scénario central mais déficitaire à faible trafic. Que doit définir le DG avant engagement ?|Les seuils de décision et le financement prudent~Il faut comprendre la sensibilité et les options de phasage ou de sortie.|La seule moyenne des scénarios extrêmes~Elle ne définit ni probabilité ni exposition financière.|Un objectif de trafic égal au seuil rentable~Fixer un objectif ne crée pas la demande.|Une provision remplaçant les mesures de maîtrise~Un traitement comptable ne fournit pas une solution opérationnelle.
Quel critère justifie une réallocation budgétaire entre sites ?|L’effet sur les priorités du réseau~La décision tient compte des risques, coûts évitables et contraintes applicables.|L’égalité stricte des montants par plateforme~Des sites différents n’ont pas les mêmes besoins.|Le taux de dépense le plus rapide~Dépenser vite ne prouve pas la meilleure utilité.|Le niveau de recettes historiques seul~L’historique ne couvre pas la criticité ni les besoins futurs.
Cas fictif : créances moyennes 6 millions, ventes annuelles à crédit 36 millions, année de 360 jours. Quel délai moyen clients ?|60 jours~6 divisé par 36, multiplié par 360, donne 60 jours.|6 jours~Six représente ici le nombre de rotations annuelles, pas le délai.|30 jours~Ce délai supposerait des créances moyennes de 3 millions.|216 jours~Ce résultat ne correspond pas au rapport créances-ventes donné.
Cas fictif : 800 000 unités facturées à 12, coûts variables de 5 par unité. Quelle contribution totale avant coûts fixes ?|5,6 millions~800 000 multiplié par la contribution unitaire de 7 donne 5,6 millions.|9,6 millions~C’est le chiffre d’affaires avant coûts variables.|4 millions~C’est le coût variable total, pas la contribution.|7 millions~Sept est la contribution unitaire et non le total demandé.
Cas fictif : investissement immédiat 2 millions, flux net unique de 2,31 millions dans un an, taux 10 %. Quelle VAN ?|0,1 million~2,31/1,10 moins 2 donne 0,1 million.|0,31 million~Ce montant ignore l’actualisation du flux futur.|0,21 million~Il ne correspond pas au flux actualisé net de l’investissement.|Moins 0,1 million~Le flux actualisé vaut 2,1 millions, supérieur à la dépense.
Cas fictif : dette de 100 000 USD, cours passant de 2 500 à 2 800 unités locales par USD. Quel surcoût local, hors frais ?|30 millions~100 000 multiplié par l’écart de 300 donne 30 millions.|300 millions~Ce montant multiplie le résultat correct par dix.|12 millions~Le pourcentage de variation ne constitue pas le montant de dette.|280 millions~C’est la dette totale au nouveau cours, pas le surcoût.
Cas fictif : budget 4 millions, dépenses payées 2,8 millions, engagements fermes non payés 0,9 million. Quelle marge non engagée ?|0,3 million~4 moins 2,8 moins 0,9 donne 0,3 million.|1,2 million~Ce montant omet les engagements restant à payer.|1,1 million~Il ne correspond pas au solde du budget engagé.|3,7 millions~C’est le total payé ou engagé, pas la marge disponible.
Une réduction des créances provient d’abandons, pas de règlements. Quel effet faut-il distinguer ?|Le nettoyage comptable et l’encaissement~Une sortie du bilan ne crée pas de trésorerie.|Une hausse du taux de recouvrement en numéraire~Aucun flux de paiement ne justifie cette conclusion.|Une baisse automatique du coût de financement~L’effet dépend des liquidités et modalités de financement.|Une amélioration certaine de la marge future~Les abandons ne démontrent pas la rentabilité des ventes futures.
Cas fictif : coût fixe 1,8 million, prix 20, coût variable 8 par unité. Quel seuil de rentabilité en volume ?|150 000 unités~1 800 000 divisé par 12 donne 150 000.|90 000 unités~Ce calcul divise par le prix au lieu de la contribution.|225 000 unités~Ce calcul divise par le coût variable.|36 000 unités~Ce volume ne couvre pas les coûts fixes donnés.
Un projet procure un gain comptable mais impose un prépaiement important. Quel document éclaire sa faisabilité immédiate ?|Un échéancier des flux et ressources autorisées~La capacité à payer dépend des dates et du financement mobilisable.|Le résultat annuel consolidé seul~Un résultat positif ne garantit pas le financement du prépaiement.|Le plan d’amortissement de l’actif~Il ne retrace pas les liquidités disponibles aux échéances.|La valeur totale du carnet de commandes~Un engagement commercial n’est pas encore un encaissement.
Les recettes d’un site baissent après changement de système. Quelle action de DG permet de séparer trafic et facturation ?|Rapprocher données opérationnelles et factures~La comparaison indépendante permet d’isoler omissions et effet de volume.|Comparer les recettes au seul budget annuel~L’écart au budget ne permet pas d’en attribuer la cause.|Relancer d’abord tous les clients au même montant~Les montants dus doivent être établis avant relance.|Modifier immédiatement les objectifs des équipes~Un nouvel objectif ne diagnostique pas la rupture de chaîne.
Un paiement urgent ne possède pas de preuve de service fait. Que décide le DG ?|Vérifier le fondement avant autorisation compétente~L’urgence appelle une procédure maîtrisée, pas la disparition des contrôles.|Signer puis demander les justificatifs à la clôture~Le paiement précède alors la vérification de la dette.|Remplacer la réception par le devis initial~Un devis ne prouve pas la prestation exécutée.|Faire attester le service par le seul fournisseur~L’attestation du créancier ne remplace pas la vérification du bénéficiaire.
Un plan d’économies réduit toutes les maintenances de 15 %. Quelle correction apporte le DG ?|Cibler les coûts selon criticité et effets~Les économies doivent préserver les fonctions et exigences essentielles.|Maintenir la coupe pour garantir l’équité des sites~Une égalité de taux ne rend pas les conséquences acceptables.|Répartir la coupe selon les valeurs comptables~La valeur nette ne reflète pas les risques du service.|Reporter la décision aux fournisseurs~Les fournisseurs ne portent pas l’ensemble des arbitrages du prestataire.
La caisse et le rapprochement bancaire sont tenus par une même personne. Quel contrôle structurel manque ?|La séparation ou un contrôle compensatoire indépendant~La vérification indépendante limite l’auto-contrôle des flux.|Une augmentation du plafond de caisse~Le plafond ne crée pas d’indépendance de contrôle.|Un budget de caisse trimestriel~Une prévision ne vérifie pas les mouvements effectivement passés.|Une signature plus rapide du rapprochement~La rapidité ne garantit pas la qualité de vérification.
Un client conteste des volumes facturés. Quel dossier doit organiser le DG ?|Les preuves de prestation et les règles de calcul~Le différend doit être tranché sur des données traçables et le cadre applicable.|Le seul relevé du chiffre d’affaires prévu~Le budget ne prouve pas la prestation contestée.|Une nouvelle facture du même montant~La réémission ne répond pas au motif du litige.|Le tarif de la plateforme la plus rentable~Une référence externe au contrat ne résout pas le différend.
Le recouvrement progresse mais les erreurs de facturation persistent. Quelle action traite la source ?|Corriger la chaîne de données et ses contrôles~Le traitement causal limite la création de nouvelles créances litigieuses.|Renforcer les relances sur toutes les nouvelles factures~La relance ne corrige pas les montants erronés.|Augmenter les provisions sur les créances~Une provision traite un risque comptable, pas le processus défectueux.|Réduire la fréquence des tableaux d’erreurs~Une visibilité moindre ne réduit pas les erreurs.
Le DG doit signer un contrat indexé en devises avec recettes locales. Que doit-il faire préparer ?|Une sensibilité de change et des réponses autorisées~L’exposition doit être chiffrée avec modalités de financement ou couverture admissibles.|Une conversion au seul cours de signature~Elle ne mesure pas le risque sur les échéances futures.|Une indexation identique des recettes sans vérification~Le DG ne peut présumer ce pouvoir ni l’accord des clients.|Une augmentation de l’amortissement~La charge comptable ne finance pas la hausse des paiements.
Un administrateur demande au DG de payer un fournisseur hors circuit. Quelle réponse convient ?|Respecter les pouvoirs et documenter la demande~Une instruction individuelle ne remplace pas les compétences et contrôles applicables.|Payer si le fournisseur est déjà connu~La relation antérieure ne suffit pas à justifier la dette et l’autorisation.|Faire signer le paiement par un subordonné~Le déplacement de signature ne rend pas l’opération régulière.|Compenser le paiement sur une facture future~Cette compensation présumée n’établit pas le fondement présent.
Le DG présente au conseil une prévision d’encaissement incertaine. Quelle information est nécessaire ?|Hypothèses, probabilités et effet des retards~Le conseil doit voir l’incertitude et les arbitrages qu’elle implique.|Le montant le plus favorable sans scénario~Il masque l’exposition financière.|La seule valeur comptable des créances~Elle ne fixe pas les dates ni la probabilité de règlement.|Un objectif commercial remplaçant la prévision~L’objectif souhaité ne constitue pas un flux attendu démontré.
Une recommandation d’audit sur les recettes est déclarée close par le service concerné. Que doit organiser le DG ?|Une vérification de mise en œuvre et d’effet~La correction du contrôle doit être testée, au-delà d’une déclaration.|Une clôture après envoi d’une note interne~La note ne prouve pas que le contrôle fonctionne.|Une clôture dès changement du chef de service~Le remplacement d’un agent ne démontre pas la correction du système.|Une validation par le client principal~Le client ne contrôle pas à lui seul le dispositif interne de recettes.
Cas fictif : une plateforme rentable facture tard et ne finance plus ses charges. Quel plan de DG est cohérent ?|Corriger l’émission et financer le décalage~La source du besoin et sa couverture transitoire doivent être traitées ensemble.|Réduire les tarifs pour accélérer le trafic~L’activité supplémentaire peut aggraver le besoin de trésorerie.|Réévaluer les actifs pour payer les fournisseurs~Une réévaluation ne produit pas de cash.|Reporter la facturation jusqu’à stabilisation du logiciel~Cela prolonge précisément le décalage qui cause la difficulté.
Cas fictif : un débiteur propose une remise de dette contre paiement immédiat partiel. Que compare le DG avant décision autorisée ?|Valeur recouvrable, délai et conditions de transaction~Il faut comparer les flux probables des options et vérifier les pouvoirs.|Montant initial de la facture et seule ancienneté~Ces données ne suffisent pas à évaluer l’alternative négociée.|Remise proposée et budget commercial restant~Le budget ne détermine pas la valeur recouvrable.|Encaissement partiel et valeur du parc technique~Cette comparaison ne mesure pas les droits et flux de la créance.
Cas fictif : le budget est respecté mais des factures reçues n’y sont pas intégrées. Quelle décision du DG est fondée ?|Reconstituer charges et engagements avant arbitrage~Le respect apparent peut résulter d’un suivi incomplet.|Distribuer la marge budgétaire affichée~Le disponible n’est pas établi tant que les obligations sont omises.|Réduire le budget suivant du montant non consommé~La sous-consommation apparente n’est pas une économie démontrée.|Mesurer la performance au seul taux de paiement~Les paiements ne couvrent pas toutes les obligations de la période.
Cas fictif : une dépense de sécurité nécessaire n’apporte aucune recette directe. Comment le DG prépare-t-il le choix financier ?|Comparer les solutions admissibles au coût complet~Le besoin de sécurité fixe les contraintes avant l’optimisation du financement.|Exiger un retour commercial positif pour toute option~Une fonction nécessaire peut ne pas avoir de recette directe.|Choisir systématiquement l’investissement le plus cher~Le prix ne garantit pas la meilleure maîtrise du besoin.|Comptabiliser une recette égale au risque évité~Un bénéfice de prévention n’est pas une recette comptable acquise.
`,[
['A','Décrivez la chaîne de recettes RVA que le DG doit contrôler entre un service effectivement rendu et son encaissement.','Identifier la preuve opérationnelle, les règles tarifaires ou contractuelles, la validation des données, l’émission et l’envoi de la facture. Suivre litiges, échéances et règlements, puis rapprocher les flux bancaires. Séparer les responsabilités et tracer les modifications. Réconcilier les prestations et les factures pour détecter les omissions, sans assimiler chiffre d’affaires, créances et liquidités.','Prestation et facturation','Recouvrement et rapprochement','Séparation et traçabilité'],
['B','Une activité commerciale RVA fictive annonce une forte croissance mais exige des investissements et paie tard. Construisez votre recommandation de DG.','Évaluer demande, capacité et marge contributive, puis les investissements et besoins en fonds de roulement. Tester les retards de paiement, la concentration clients et un scénario de faible trafic. Comparer phasage, garanties et engagements de volume. Présenter un plan financé et des seuils de décision dans les délégations applicables, avec suivi des encaissements plutôt que du seul chiffre d’affaires.','Rentabilité et capacité','BFR et scénarios','Plan financé et engagements'],
['C','Cas fictif : chiffre d’affaires 30 millions, coûts variables 12 millions, coûts fixes 15 millions. Calculez contribution, résultat et seuil de chiffre d’affaires à taux de contribution constant.','La contribution est de 18 millions, soit 60 % du chiffre d’affaires. Le résultat est de 3 millions avant autres postes. Le seuil de chiffre d’affaires vaut 15/0,60, soit 25 millions, sous hypothèses de mix, tarifs, coûts variables unitaires et capacité constants. Distinguer ce résultat comptable des flux encaissés et tester la sensibilité aux volumes.','Contribution 18 millions et 60 %','Résultat 3 millions','Seuil 25 millions et hypothèses'],
['C','Cas fictif : créances moyennes 4,5 millions, ventes annuelles à crédit 27 millions, année de 360 jours. Quel délai clients et quelle libération théorique si le délai descend à 40 jours ?','Le délai initial vaut 4,5/27 × 360, soit 60 jours. À ventes constantes, les créances à 40 jours seraient de 3 millions, ce qui libérerait théoriquement 1,5 million. Vérifier les créances réellement recouvrables et les dates de paiement. Fixer un plan par débiteur, corriger la facturation et suivre les encaissements sans promettre une libération certaine.','Délai initial 60 jours','Créances cibles 3 millions','Libération théorique 1,5 million'],
['D','Une migration fictive du logiciel de recettes RVA entraîne des écarts de volume et des doubles factures. Organisez la réponse exécutive.','Préserver les données, suspendre les traitements erronés et maintenir une facturation maîtrisée. Rapprocher les prestations, référentiels tarifaires, factures et règlements, identifier les clients affectés et régulariser avec traçabilité. Désigner des responsables métiers et informatiques, tester les corrections et communiquer sur les litiges. Vérifier ensuite l’exhaustivité et l’unicité avant retour complet au processus normal.','Protection et rapprochement','Régularisation traçable','Tests et contrôle d’exhaustivité'],
['D','La RVA fictive paie des pénalités malgré un budget de maintenance respecté. Quelle investigation et quelles mesures dirigez-vous ?','Relier pénalités et interruptions aux actifs, contrats et causes. Examiner la qualité de maintenance, délais de pièces, compétences, exclusions contractuelles et arbitrages budgétaires. Comparer le coût complet du service plutôt que la seule enveloppe d’entretien. Prioriser les corrections financées avec responsables et délais, puis mesurer disponibilité, récurrence et pénalités pour vérifier l’effet.','Causes et coût complet','Plan correctif financé','Indicateurs d’efficacité'],
['D','Un recouvrement fictif repose sur des relances nombreuses mais sans segmentation. Comment le DG le réorganise-t-il ?','Segmenter les créances par ancienneté, litige, solvabilité et montant ; vérifier la preuve des prestations et traiter les erreurs à la source. Attribuer chaque dossier à un responsable, fixer des encaissements et échéances réalistes, négocier dans les pouvoirs autorisés et escalader les cas pertinents. Suivre promesses tenues, règlements et nouvelles créances, avec rapprochement bancaire et contrôle indépendant.','Segmentation et preuves','Responsables et échéances','Encaissements et contrôle'],
['E','Un administrateur RVA souhaite choisir personnellement les clients bénéficiant d’un abandon de créance. Que faites-vous comme DG ?','Vérifier les pouvoirs et règles applicables aux transactions, remises et abandons. Préparer une analyse objective de recouvrabilité et des alternatives, traiter les conflits d’intérêts et tracer les critères. Soumettre les décisions à l’organe compétent plutôt qu’appliquer une instruction individuelle. Enregistrer fidèlement la décision et distinguer abandon comptable, transaction et règlement encaissé.','Pouvoirs et critères','Conflits et décision compétente','Distinction abandon et encaissement'],
['E','Le comité d’audit RVA demande les éléments d’une créance litigieuse importante. Quelle posture de DG adoptez-vous ?','Fournir les contrats, preuves de prestation, factures, contestations et hypothèses de recouvrabilité, avec les limites connues. Associer les services compétents et faciliter l’examen indépendant. Conserver la responsabilité de gestion et exécuter les décisions régulières dans les pouvoirs applicables. Corriger l’information si nécessaire sans cacher le risque ni demander au comité de gérer directement les relances.','Information complète et limites','Examen indépendant','Responsabilité exécutive'],
['F','Cas fictif : dette en devises, encaissements retardés et maintenance critique exigible sous quinze jours. Proposez votre plan de DG et son financement.','Établir un échéancier de trésorerie et tester change et retards clients. Protéger le service critique par une réponse technique et financière admissible. Cibler le recouvrement probable, négocier les échéances non critiques et étudier les ressources autorisées ; ne pas compter des créances incertaines comme cash acquis. Soumettre les arbitrages hors délégation et suivre quotidiennement les flux et l’exécution.','Prévision et sensibilités','Priorité critique et moyens','Financement autorisé et suivi'],
]);

pack(4,'Transformation, investissements et équipes',`
Un équipement livré n’est pas encore intégré au service. Quel jalon établit le mieux sa valeur opérationnelle ?|L’acceptation du service après essais d’intégration~La valeur dépend du fonctionnement réel dans sa chaîne d’usage.|La réception physique du matériel sur site~Elle établit la livraison, pas le fonctionnement intégré.|La validation de la facture d’acquisition~Elle porte sur le paiement et non sur la capacité utilisable.|La mise à jour du registre des immobilisations~L’enregistrement comptable ne prouve pas l’aptitude au service.
Un projet numérique RVA automatise un processus dont les données de base sont incohérentes. Quel préalable est déterminant ?|Fiabiliser les données et règles de gestion~L’automatisation reproduit les défauts du processus si les règles restent incohérentes.|Augmenter la puissance des serveurs~La capacité de calcul ne corrige pas le sens des données.|Former les utilisateurs à cliquer plus vite~La vitesse d’exécution ne fiabilise pas les référentiels.|Élargir le nombre de tableaux de bord~Des tableaux supplémentaires peuvent reproduire les mêmes erreurs.
La transformation réduit le temps d’une tâche mais allonge l’attente du service suivant. Quel niveau de mesure privilégier ?|Le délai de bout en bout du service~Il révèle le transfert du goulot entre étapes.|Le temps de saisie de la tâche modifiée~Il ne couvre pas l’attente créée en aval.|Le nombre de comptes utilisateurs actifs~Il mesure l’adoption et non le résultat du processus.|Le volume de formations réalisées~Il mesure des moyens sans démontrer le délai final.
Quel besoin couvre la gestion de configuration d’un système critique ?|Connaître et maîtriser la version réellement utilisée~Elle relie l’installation, sa documentation et les modifications autorisées.|Déterminer le montant de sa valeur nette~La valorisation comptable n’identifie pas la configuration opérationnelle.|Négocier les prix des pièces identiques~L’achat ne définit pas les versions et changements autorisés.|Mesurer la satisfaction générale du personnel~Cette mesure ne contrôle pas l’état technique installé.
Le prestataire conserve les seules sauvegardes exploitables. Quel risque spécifique est en jeu ?|La dépendance de reprise et de réversibilité~L’entreprise peut être incapable de restaurer ou transférer son service.|La seule variation du prix de licence~Le problème d’accès aux données dépasse le prix.|La durée d’amortissement du logiciel~Elle ne mesure pas l’autonomie de restauration.|La fréquentation des espaces commerciaux~Ce volume ne renseigne pas la capacité de reprise numérique.
Un grand aéroport et un petit site ont des coûts unitaires différents. Quel facteur doit être examiné avant classement ?|L’échelle, le mix et les contraintes de service~Les comparaisons doivent tenir compte des fonctions et volumes servis.|Le nombre de pages de leurs rapports~La forme du rapport ne rend pas les périmètres comparables.|La seule ancienneté des directeurs~L’ancienneté ne suffit pas à expliquer l’écart structurel.|Le classement historique du chiffre d’affaires~Le revenu ne décrit pas les coûts et obligations des sites.
Une qualification est valide mais l’agent n’a pas pratiqué la nouvelle procédure. Que doit distinguer le DG ?|Validité formelle et aptitude au changement~La préparation au nouveau contexte nécessite une vérification adaptée.|Ancienneté professionnelle et statut contractuel~Cette distinction ne vérifie pas la maîtrise de la nouvelle procédure.|Coût de formation et coût salarial~Le coût ne démontre pas la compétence opérationnelle.|Effectif budgété et effectif administratif~Ces décomptes ne prouvent pas l’aptitude de l’agent.
Un calendrier de travaux comporte une tâche qui retarde toute la mise en service dès qu’elle glisse. Que représente-t-elle ?|Une activité du chemin critique~Son retard affecte la date finale dans le réseau de dépendances considéré.|Une activité à coût variable~La structure de coût ne définit pas son effet sur le délai.|Une activité administrativement prioritaire~Une priorité affichée ne prouve pas l’absence de marge de délai.|Une activité nécessairement sous-traitée~Le mode d’exécution ne définit pas le chemin critique.
Pourquoi un « budget consommé à 90 % » ne prouve-t-il pas un projet presque terminé ?|Dépenses et avancement physique peuvent diverger~Les paiements peuvent précéder les travaux ou financer des reprises.|Les avances sont toujours interdites~L’existence et les conditions des avances dépendent du cadre applicable.|Les dépenses sont nécessairement mal enregistrées~Une divergence peut exister même avec une comptabilité exacte.|Les équipements payés n’ont aucune valeur~Le paiement ne mesure pas l’achèvement mais peut correspondre à des actifs réels.
Un chantier ne peut se dérouler qu’en fenêtres compatibles avec l’exploitation. Quelle base de planification retient le DG ?|Un calendrier intégré travaux-exploitation~Les contraintes de service et les moyens doivent être arbitrés ensemble.|Le calendrier nominal du fournisseur seul~Il peut ignorer les fenêtres et interfaces du site.|La date de fin correspondant au budget annuel~Une échéance budgétaire ne garantit pas la faisabilité technique.|Le programme commercial sans réserve de chantier~Il peut supprimer les créneaux nécessaires aux travaux.
Quel critère autorise une généralisation après un pilote numérique ?|Les résultats et limites selon les critères prévus~La décision se fonde sur les bénéfices, risques et écarts observés.|La dépense complète du budget d’essai~Consommer le budget ne prouve pas la réussite.|Le nombre d’utilisateurs ayant créé un compte~L’inscription ne démontre pas le service réellement amélioré.|La satisfaction du seul fournisseur~L’avis du vendeur ne remplace pas les résultats vérifiés.
Un projet initialement utile devient moins rentable après baisse durable du trafic. Que prépare le DG ?|Une réévaluation des options futures~Il faut comparer poursuite, phasage, réduction et arrêt avec leurs conséquences.|Une poursuite fondée sur les dépenses déjà engagées~Les coûts irrécupérables ne rendent pas la suite utile.|Une extension pour absorber les frais passés~L’accroissement de capacité ne crée pas la demande.|Une nouvelle prévision égale au trafic initial~Modifier la prévision sans preuve ne corrige pas l’économie du projet.
Une technologie accroît la performance mais impose une dépendance exclusive de dix ans. Quelle dimension doit entrer au dossier ?|Le coût et les conditions de sortie~La dépendance doit être évaluée sur tout le cycle de vie.|La seule rapidité de livraison initiale~Elle ne mesure pas la capacité de sortie du contrat.|Le seul montant de la licence de départ~Il omet les coûts futurs de support et de migration.|Le nombre de fonctions présentées en démonstration~La richesse fonctionnelle ne réduit pas nécessairement la dépendance.
Le DG veut renforcer les compétences rares sur plusieurs sites. Quelle approche est la plus soutenable ?|Un plan de compétences relié aux besoins de service~Il combine qualifications, pratiques, suppléances et calendrier de disponibilité.|Une même formation annuelle pour tous les métiers~L’uniformité ignore les compétences spécifiques requises.|Une prime de présence sans évaluation technique~La présence ne prouve pas la maîtrise des fonctions.|Une rotation immédiate de tous les agents~Le transfert doit respecter qualifications et besoins de continuité.
Un projet transversal n’a pas de responsable des bénéfices après livraison. Quel risque en découle ?|Une réalisation technique sans résultat piloté~Les gains de service nécessitent une appropriation et un suivi après livraison.|Une impossibilité certaine de recevoir le matériel~La réception matérielle peut avoir lieu sans suivi des bénéfices.|Une annulation automatique des garanties~Le contrat ne prévoit pas nécessairement cet effet.|Une hausse mécanique de la valeur de revente~Aucun lien ne démontre cet effet financier.
Quel engagement contractuel prépare le mieux la réversibilité d’un système ?|Des livrables transférables et des essais de reprise~L’accès utilisable aux données, configurations et compétences doit être vérifié.|Une pénalité élevée à la fin du contrat~Une indemnité ne restitue pas les moyens de continuer le service.|Une remise sur le prochain renouvellement~Elle favorise la reconduction sans garantir la sortie.|Une copie du seul manuel commercial~Ce document ne suffit pas à reconstruire l’environnement opérationnel.
Une réforme mobilise les mêmes experts que l’exploitation courante. Quelle contrainte doit intégrer le DG ?|La capacité réelle de changement des équipes~La charge de transformation doit préserver le service et les qualifications.|Le seul nombre de postes autorisés~Le plafond ne renseigne pas la disponibilité des personnes compétentes.|La seule durée contractuelle du projet~Le contrat ne crée pas de ressources internes.|La moyenne des congés de l’année précédente~Elle ne décrit pas les conflits de charge actuels.
Une solution a le meilleur prix mais nécessite une mise à niveau coûteuse du réseau. Quel arbitrage est pertinent ?|Comparer les ensembles techniques complets~Les prérequis et interfaces doivent être intégrés au coût de l’option.|Retenir le seul prix du composant principal~Il sous-estime les dépenses nécessaires à son fonctionnement.|Imputer le réseau à un autre budget et l’exclure~Le changement d’enveloppe ne supprime pas le coût pour l’entreprise.|Repousser l’étude du réseau après commande~Le choix devient engagé avant validation d’un prérequis majeur.
Cas fictif : budget total 10 millions, avancement physique valorisé au budget 4 millions, coût réel 5 millions. Quel écart de coût en valeur acquise ?|Moins 1 million~La valeur acquise de 4 moins le coût réel de 5 donne moins 1.|Plus 1 million~Le signe inversé présente à tort le surcoût comme favorable.|Moins 6 millions~Ce calcul confond budget total et avancement acquis.|Plus 5 millions~Ce montant ne représente pas l’écart de coût.
Cas fictif : équipement 2 millions, installation 0,3 million, formation 0,1 million et support sur la période 0,6 million. Quel coût comparatif non actualisé ?|3 millions~La somme des quatre postes est de 3 millions.|2 millions~Ce montant ignore les coûts complémentaires.|2,4 millions~Ce total omet le support sur la période.|2,6 millions~Ce total ne couvre pas l’ensemble des postes donnés.
Cas fictif : projet produisant 0,4 million d’économies annuelles, coût initial 2 millions. Quel délai simple de récupération, sans actualisation ?|5 ans~2 divisé par 0,4 donne cinq ans.|0,2 an~Ce calcul inverse le rapport demandé.|2,4 ans~L’addition de montants ne donne pas un délai.|4 ans~Ce délai ne permettrait de récupérer que 1,6 million.
Cas fictif : prix de base 1,5 million, hausse contractuelle de 8 %. Quel supplément ?|120 000~1 500 000 multiplié par 8 % donne 120 000.|1 620 000~C’est le prix révisé total et non le supplément.|12 000~Ce résultat réduit la hausse d’un facteur dix.|187 500~Ce montant ne correspond pas à une hausse de 8 %.
Le coût à terminaison d’un projet augmente. Quelle décomposition aide le DG à décider ?|Coûts engagés, reste à faire et risques~Elle distingue les dépenses passées des choix et incertitudes futurs.|Dépenses payées et budget initial seulement~Le reste à faire et les engagements sont absents.|Nombre de factures et durée du contrat~Ces volumes ne suffisent pas à estimer l’achèvement.|Valeur comptable et montant assuré des actifs~Ces valeurs ne décrivent pas les travaux restants.
Un fournisseur propose un crédit moins cher mais lié à des pièces exclusives coûteuses. Quelle analyse convient ?|Financement et coût de cycle de vie~Le gain d’intérêt doit être comparé à la dépendance et aux charges futures.|Le seul taux nominal du crédit~Un taux inférieur peut masquer un coût global plus élevé.|La seule mensualité de la première année~L’échéance ne couvre pas les pièces et obligations du cycle.|Le montant maximal de crédit disponible~La capacité à emprunter ne prouve pas l’intérêt économique.
Cas fictif : la provision pour risque est de 0,2 million sur un budget de 4 millions. Quelle part du budget représente-t-elle ?|5 %~0,2 divisé par 4 donne 5 %.|20 %~Ce taux ne correspond pas au rapport donné.|0,5 %~Ce résultat comporte une erreur d’échelle.|2 %~Ce taux correspondrait à 0,08 million.
Une comparaison achat-location utilise cinq ans pour l’achat et deux ans pour la location. Que doit corriger le DG ?|L’horizon et le service comparés~Les options doivent être ramenées à une durée et une capacité cohérentes.|Le nom des fournisseurs dans le tableau~L’anonymisation ne corrige pas l’inégalité des horizons.|Le montant de la location pour égaler l’achat~Le résultat ne doit pas être imposé à la comparaison.|La durée d’amortissement pour annuler l’écart~Le traitement comptable ne remplace pas la comparaison économique.
Le matériel est livré mais les opérateurs ne sont pas formés. Quel statut du projet doit retenir le DG ?|Livraison réalisée, service non encore prêt~La disponibilité opérationnelle dépend aussi des compétences et validations.|Mise en service acquise par la réception~La livraison ne remplit pas les prérequis humains.|Bénéfices réalisés à hauteur des factures payées~Les paiements ne prouvent pas les gains de service.|Projet sans risque puisque l’actif est assuré~L’assurance ne fournit pas des opérateurs compétents.
Un changement informatique modifie les calculs de redevances. Quelle validation est nécessaire avant bascule ?|Des tests métiers sur cas et tarifs applicables~Il faut vérifier les montants, exceptions et données de bout en bout.|Le seul test de connexion des utilisateurs~La connexion ne garantit pas l’exactitude des calculs.|La copie des anciennes factures en archive~L’archivage ne valide pas le nouveau moteur de calcul.|La validation de la charte graphique~La présentation ne prouve pas l’exactitude financière.
Le chantier accuse un retard ; le fournisseur propose de supprimer les essais pour tenir la date. Quelle décision prend le DG ?|Replanifier en conservant les critères d’acceptation~Un calendrier doit être corrigé sans supprimer la preuve de fonctionnement requis.|Réduire les essais au montant du budget restant~Le budget ne définit pas les vérifications nécessaires.|Accepter si la garantie contractuelle est prolongée~La garantie ne remplace pas l’acceptation technique.|Transférer la réception au service commercial~Le changement de signataire ne réalise pas les essais.
Des agents contournent le nouvel outil parce qu’il ne couvre pas certains cas réels. Que fait d’abord le DG ?|Analyser les cas et adapter le processus contrôlé~L’écart d’usage peut révéler un défaut de conception à traiter.|Bloquer les anciens accès sans solution de continuité~Cela peut supprimer le seul moyen de traiter les cas non couverts.|Accroître les sanctions sans examiner les cas~Cette réponse ne traite pas une éventuelle lacune fonctionnelle.|Compter les connexions pour déclarer l’adoption~Une connexion ne prouve pas l’usage effectif et correct du processus.
La transformation atteint ses livrables mais les gains annoncés n’apparaissent pas. Quelle revue lance le DG ?|Une revue des bénéfices et des hypothèses~Il faut examiner l’usage réel, les changements de contexte et les actions complémentaires.|Une revue des seuls achats du projet~Elle ne couvre pas les conditions d’utilisation et de gains.|Une validation des gains égale au budget dépensé~Une dépense n’est pas un bénéfice de service.|Une clôture après signature du dernier procès-verbal~La clôture documentaire ne résout pas l’absence de résultat.
Deux sites utilisent des versions différentes d’une procédure critique. Quelle réponse structurelle convient ?|Maîtriser les versions et leur déploiement~La procédure applicable, les formations et retraits doivent être traçables.|Envoyer une nouvelle note sans vérifier l’usage~La diffusion seule ne prouve pas l’application de la bonne version.|Laisser chaque site retenir la version préférée~Des variations non maîtrisées peuvent affecter les interfaces.|Remplacer les responsables avant toute vérification~Le défaut peut relever du système documentaire et de diffusion.
Un projet mobilise un expert unique proche du départ. Quelle décision réduit le risque de DG ?|Organiser un transfert de compétences vérifié~La documentation, la pratique et une relève préparée réduisent la dépendance.|Reporter les travaux jusqu’au recrutement d’un profil identique~Le report ne traite pas la perte imminente de connaissance.|Prolonger son accès sans définir de relais~L’accès ne crée pas une capacité durable de remplacement.|Acheter des licences supplémentaires~Le nombre de licences ne remplace pas l’expertise.
Le DG reçoit une demande de modification qui dépasse le budget approuvé. Que prépare-t-il ?|Un dossier d’impact et l’autorisation compétente~Coût, délai, risques et bénéfices doivent être réévalués avant engagement.|Une commande séparée sous le seuil de signature~Le fractionnement ne résout pas la compétence sur le changement.|Une acceptation technique valant accord budgétaire~Les pouvoirs techniques et financiers ne sont pas interchangeables.|Une imputation sur l’entretien courant sans analyse~Le changement d’imputation ne valide pas la dépense.
Un fournisseur rédige seul des spécifications correspondant exclusivement à son produit. Quelle mesure du DG protège la sélection ?|Une définition indépendante du besoin fonctionnel~Les exigences doivent être justifiées par le service et évaluables équitablement.|Une réduction générale du prix demandé~Un rabais ne corrige pas des critères verrouillés.|Une confirmation écrite du même fournisseur~Elle ne rend pas la définition indépendante.|Une publication plus longue du même dossier~Le délai ne corrige pas une restriction injustifiée du besoin.
La direction veut annoncer un projet terminé avant les réserves critiques levées. Quel compte rendu fait le DG ?|Livrables acquis, réserves et conditions restantes~L’information doit distinguer progrès réel et aptitude opérationnelle.|Achèvement complet dès paiement du solde~Le paiement ne prouve pas la levée des réserves.|Achèvement complet avec annexe non transmise~L’omission des limites rend l’information trompeuse.|Report de toute information jusqu’à la clôture parfaite~Le conseil doit disposer d’une information utile en cours d’exécution.
Cas fictif : économie attendue du logiciel, erreurs de données et rejet des équipes. Quelle séquence du DG est appropriée ?|Fiabiliser le processus puis tester l’usage~Les gains dépendent de données correctes et d’une adoption opérationnelle.|Déployer partout pour homogénéiser plus vite~Cela peut généraliser les erreurs et les contournements.|Réduire les effectifs avant le pilote~Les gains de charge ne sont pas encore démontrés.|Acheter une capacité serveur supplémentaire~La capacité technique ne traite pas les deux causes décrites.
Cas fictif : chantier à moitié réalisé, nouvelle contrainte de sécurité et trésorerie réduite. Quel arbitrage prépare le DG ?|Options futures sûres avec coût de terminaison~Il faut comparer les solutions admissibles et leur financement restant.|Poursuite identique pour protéger les dépenses passées~Les dépenses irrécupérables ne valident pas la solution actuelle.|Arrêt définitif fondé sur le seul solde bancaire~Les obligations, solutions de transition et coûts d’arrêt doivent être étudiés.|Extension du périmètre pour attirer un financeur~Un périmètre accru peut aggraver la charge et les risques.
Cas fictif : départ d’un prestataire, formats propriétaires et aucune restauration testée. Quelle action prioritaire du DG ?|Sécuriser l’accès et tester une reprise maîtrisée~La continuité exige des données utilisables, des droits et des compétences vérifiés.|Commander un nouvel outil sans inventaire des données~La migration reste incertaine sans connaître les dépendances.|Clore le contrat dès récupération d’un disque~Un support reçu ne prouve pas que les données sont exploitables.|Conserver les mots de passe du fournisseur sans revue~La sécurité et les droits d’accès doivent être maîtrisés.
Cas fictif : un pilote réduit le délai mais accroît les erreurs de facturation. Quelle conclusion du DG est justifiée ?|Les critères de généralisation ne sont pas tous atteints~Le gain de vitesse doit être évalué avec la qualité et les risques.|Le pilote est réussi puisque le délai baisse~Un résultat partiel ne suffit pas à valider tous les objectifs.|Le pilote est définitivement inutile~Des corrections peuvent permettre un nouvel essai utile.|Le taux de connexion compense les erreurs~L’usage de l’outil ne neutralise pas les erreurs financières.
`,[
['A','Expliquez pourquoi réception physique, acceptation technique, mise en service et réalisation des bénéfices constituent des étapes différentes d’un investissement RVA.','La réception constate la livraison ; l’acceptation vérifie les exigences et essais applicables. La mise en service suppose aussi interfaces, qualifications, documentation et validations. Les bénéfices se mesurent ensuite sur le service, les coûts ou les risques. Le DG affecte un responsable à chaque étape, traite les réserves et suit les résultats au-delà des factures et procès-verbaux.','Étapes distinguées','Prérequis opérationnels','Responsables et bénéfices'],
['B','Un projet RVA fictif est devenu moins utile après une baisse durable du trafic. Comment recommandez-vous sa suite au conseil en tant que DG ?','Réviser les prévisions et comparer les flux futurs de poursuite, phasage, réduction ou arrêt. Distinguer dépenses irrécupérables et coûts évitables, examiner sécurité, contrats, financement et effets réseau. Proposer une option argumentée avec seuils de décision et conséquences. Soumettre l’arbitrage compétent puis organiser l’exécution et le suivi, sans défendre le projet uniquement pour justifier les dépenses passées.','Options et flux futurs','Coûts irrécupérables distingués','Recommandation et exécution'],
['C','Cas fictif : budget du projet 12 millions, valeur acquise 6 millions, coût réel 8 millions. Calculez l’indice de performance des coûts et l’estimation à terminaison si cette performance reste constante.','L’indice de performance des coûts vaut 6/8, soit 0,75. Si cette performance reste identique, l’estimation à terminaison vaut 12/0,75, soit 16 millions, donc 4 millions au-dessus du budget. Vérifier la qualité de l’avancement et les engagements puis confronter cette extrapolation à une estimation du reste à faire et des risques avant arbitrage.','Indice de 0,75','Estimation de 16 millions','Hypothèse et reste à faire'],
['C','Deux options fictives assurent le même service sur cinq ans : achat 2 millions plus 0,2 million annuel d’entretien, ou location 0,65 million annuel entretien compris. Comparez sans actualisation ni valeur résiduelle.','L’achat coûte 2 + 5 × 0,2 = 3 millions ; la location coûte 5 × 0,65 = 3,25 millions. L’écart simple est de 0,25 million en faveur de l’achat. Examiner toutefois dates de paiement, financement, clauses, disponibilité, risques et valeur résiduelle exclus de ce calcul. Ne pas transformer cette comparaison simplifiée en décision définitive.','Achat 3 millions','Location 3,25 millions','Écart et limites'],
['D','Un nouveau système RVA fictif fonctionne chez le fournisseur mais échoue sur site. Organisez le redressement du projet comme DG.','Maintenir un service de continuité admissible et documenter les écarts de site. Examiner alimentation, interfaces, données, configuration, environnement et compétences. Mobiliser responsables internes et fournisseur sur un plan correctif avec jalons, coûts et obligations contractuelles. Organiser les essais représentatifs et l’acceptation compétente, puis contrôler le fonctionnement réel avant de déclarer la mise en service.','Continuité et diagnostic de site','Plan conjoint et responsabilités','Essais et acceptation'],
['D','Un programme numérique RVA fictif surcharge les experts qui assurent aussi les opérations. Comment ajustez-vous le portefeuille en tant que DG ?','Évaluer la charge réelle, les compétences rares et les fenêtres d’exploitation. Prioriser les projets par risque, dépendance et bénéfice ; rephaser ou limiter le périmètre pour préserver les fonctions essentielles. Prévoir renforts, transfert de connaissances et suppléances qualifiées. Revoir les jalons et budgets avec les décideurs compétents et suivre capacité disponible, fatigue et avancement.','Charge et compétences','Priorisation et phasage','Renforts et suivi'],
['D','Les équipes RVA fictives contournent un outil de recettes récemment déployé. Décrivez une conduite du changement orientée résultats.','Écouter les utilisateurs et analyser les cas non couverts, erreurs et contraintes de charge. Stabiliser les données et processus avec les métiers, maintenir un mode de continuité contrôlé puis tester les corrections. Former sur des cas réels, désigner des relais et mesurer usage correct, délais et qualité. Généraliser selon critères explicites, sans assimiler connexions et bénéfices.','Analyse des usages réels','Corrections et formation','Mesure de qualité et bénéfices'],
['E','Un fournisseur propose de financer l’étude qui définira les spécifications du futur marché RVA auquel il candidatera. Comment traitez-vous cette proposition comme DG ?','Identifier le risque d’influence et vérifier les règles applicables. Conserver une définition indépendante et traçable du besoin, examiner les alternatives et éviter des exigences injustifiées propres au fournisseur. Encadrer tout apport d’information pour préserver confidentialité et équité, traiter les conflits et faire valider la procédure par les fonctions compétentes. Ne pas considérer la gratuité comme preuve d’impartialité.','Influence identifiée','Besoin indépendant','Équité et validation compétente'],
['E','Le conseil demande une accélération d’un chantier RVA fictif qui suppose une modification coûteuse et des risques nouveaux. Quel dossier lui présentez-vous comme DG ?','Chiffrer les options d’accélération, leurs gains de délai, impacts sur exploitation, risques et coût à terminaison. Vérifier les prérequis et critères d’acceptation maintenus, ainsi que les obligations contractuelles et les pouvoirs d’engagement. Formuler une recommandation financée et un calendrier réaliste. Faire décider l’organe compétent puis organiser la réalisation et un compte rendu fidèle.','Options coût-délai-risque','Prérequis et compétences','Décision financée et suivi'],
['F','Cas fictif : projet en retard, réserve technique critique et communication publique prévue demain. Que décidez-vous comme DG RVA ?','Faire évaluer la réserve et maintenir les protections et essais nécessaires. Établir le reste à faire, les responsabilités, le coût et le calendrier réaliste. Communiquer les progrès réels et les conditions restantes sans annoncer une aptitude non démontrée. Soumettre les arbitrages compétents, financer le redressement et suivre des jalons vérifiables, sans supprimer les critères de sécurité pour tenir une annonce.','Réserve et protections','Plan de redressement','Communication fidèle'],
]);

pack(5,'Crises, gouvernance et arbitrages de direction',`
Une crise touche simultanément plusieurs plateformes RVA. Quelle unité de pilotage faut-il organiser ?|Une coordination réseau avec responsabilités locales~Elle permet les arbitrages communs tout en conservant la conduite locale habilitée.|Une cellule centrale validant chaque geste technique~La centralisation de tous les gestes peut saturer et contourner les habilitations.|Des cellules locales sans partage de situation~Les dépendances et ressources communes ne seraient pas arbitrées.|Une cellule fournisseur décidant pour tous les sites~Le fournisseur ne porte pas l’ensemble des compétences de l’entreprise.
Un rapport confond cause immédiate et cause organisationnelle d’un incident. Quelle distinction explique le DG ?|Le déclencheur et les conditions qui l’ont permis~L’analyse doit relier l’événement aux barrières et décisions du système.|Le coût assuré et le coût non assuré~Il s’agit d’une ventilation financière, pas d’une distinction causale.|Le site d’origine et le site le plus rentable~La rentabilité ne définit pas le niveau de cause.|La date de détection et la date de facture~Ces dates ne suffisent pas à expliquer le mécanisme de l’incident.
Une mesure réduit la fréquence des pannes mais allonge leur durée. Quel indicateur complémentaire est indispensable ?|Le temps d’indisponibilité du service~L’effet total dépend aussi de la durée et du périmètre des interruptions.|Le seul nombre de pannes annuelles~Il ne reflète pas l’allongement des arrêts.|Le nombre de commandes de pièces~Les achats ne mesurent pas directement le service indisponible.|La moyenne d’âge des responsables~Cette donnée ne quantifie pas l’effet des interruptions.
Deux fournisseurs différents utilisent le même centre de données. Quelle propriété de résilience manque potentiellement ?|La diversité des dépendances sous-jacentes~Deux contrats peuvent rester exposés à une même défaillance physique.|La diversité des raisons sociales~Elle existe déjà et ne garantit pas l’indépendance technique.|La différence de dates de facturation~Le calendrier financier ne protège pas d’une panne commune.|La différence de prix de catalogue~Des prix distincts ne rendent pas les infrastructures indépendantes.
Après une crise, une indemnité couvre les dégâts matériels. Quelle conclusion est exacte pour le DG ?|Le risque causal peut rester entier~L’indemnisation ne prouve pas la suppression de la défaillance.|La remise en service est techniquement validée~Le paiement de l’assureur ne remplace pas les validations compétentes.|La continuité future est garantie par le contrat~Une indemnité financière ne fournit pas le service opérationnel.|La responsabilité de prévention passe à l’assureur~L’entreprise conserve ses responsabilités de gestion et de sécurité.
Un scénario crédible a une faible probabilité mais un effet majeur. Quelle lecture doit retenir le DG ?|Faible fréquence ne signifie pas faible criticité~La gravité, les barrières et les critères d’acceptation doivent être examinés.|Il doit être classé derrière tous les incidents fréquents~La fréquence seule ne suffit pas à hiérarchiser les risques.|Il relève exclusivement du budget d’assurance~L’assurance ne remplace pas la prévention et la continuité.|Il peut être retiré s’il n’est jamais survenu~L’absence historique ne prouve pas l’impossibilité future.
Quel document permet un partage de situation fiable entre directions pendant une crise ?|Un état horodaté des faits et actions~Il distingue observations, hypothèses, responsables et décisions en cours.|Un résumé sans heure pour rester facilement réutilisable~L’évolution rapide rend les données non datées ambiguës.|Le dernier rapport annuel approuvé~Il ne décrit pas la situation opérationnelle présente.|Une compilation des messages sans validation~Elle peut amplifier rumeurs et contradictions sans établir les faits.
La crise porte sur une panne non intentionnelle ; un accès distant suspect est découvert ensuite. Quelle réponse conceptuelle convient ?|Examiner ensemble les dimensions sécurité et cyber~La sûreté numérique peut affecter la sécurité et la continuité du service.|Requalifier toutes les défaillances comme malveillance~L’indice doit être instruit sans présumer sa causalité.|Limiter l’analyse au matériel déjà en panne~Cela exclurait une piste utile et un risque potentiellement actif.|Attendre la preuve pénale avant toute protection~Des mesures conservatoires proportionnées peuvent être nécessaires avant cette preuve.
Le DG veut comparer gravité potentielle et gravité effectivement observée. Pourquoi ?|Un quasi-accident peut révéler une barrière fragile~L’absence de dommage final ne signifie pas que l’exposition était faible.|La gravité potentielle remplace toute donnée réelle~Les faits restent nécessaires pour une analyse crédible.|La gravité observée suffit toujours à classer le risque~Elle peut sous-estimer un événement évité de justesse.|Le coût du dommage résume toute la sécurité~Des conséquences humaines et opérationnelles dépassent ce seul montant.
Un plan de crise prévoit tout réparer avant de rétablir le moindre service. Quel ajustement stratégique étudie le DG ?|Une reprise graduée des fonctions prioritaires~Un service minimal admissible peut être rétabli avant la restauration complète.|Une réouverture totale selon le calendrier médiatique~La communication ne définit pas la capacité sûre disponible.|Une réparation des seuls actifs les plus coûteux~Le prix ne mesure pas la priorité de service.|Une reprise identique pour toutes les plateformes~Les dommages, risques et moyens peuvent différer par site.
Une crise absorbe les moyens des projets de croissance. Comment le DG prépare-t-il la reprogrammation ?|Prioriser continuité et engagements avec options~Le portefeuille doit être révisé selon risques, ressources et effets futurs.|Préserver chaque calendrier pour rassurer les partenaires~Des engagements irréalisables peuvent aggraver la crise.|Répartir les retards également entre tous les projets~L’égalité de retard ignore les dépendances et priorités.|Annuler tous les projets sans coût de sortie~Les effets contractuels et les besoins critiques doivent être évalués.
Un financeur propose une ressource fléchée vers un projet non prioritaire pendant la crise. Quel examen est nécessaire ?|Effet global, contreparties et charges futures~Un financement dédié peut mobiliser des ressources rares et créer des charges.|Montant obtenu comparé aux financements des autres sites~Le montant ne démontre pas l’utilité pour la crise actuelle.|Taux d’intérêt sans examiner l’objet du projet~Un taux favorable ne suffit pas à justifier l’investissement.|Possibilité de communiquer rapidement sur l’accord~La visibilité ne mesure pas la pertinence opérationnelle et financière.
Quel engagement commercial le DG peut-il préparer pendant une reprise incertaine ?|Une offre liée à la capacité validée et aux limites~Les engagements doivent refléter la réalité du service et les conditions de reprise.|Un volume égal au maximum de l’année passée~L’historique ne prouve pas la capacité après sinistre.|Une garantie totale fondée sur l’assurance~L’assurance financière ne garantit pas l’exploitation.|Un programme complet compensé par des remises futures~Des remises ne rétablissent pas une capacité absente.
Un partenariat de continuité avec un tiers nécessite un transfert de données. Quel dossier doit être instruit ?|Service, droits, sécurité et réversibilité~La solution doit être exploitable et maîtrisée au-delà de sa capacité annoncée.|La seule bande passante proposée par le tiers~Le débit ne couvre pas les droits, accès et conditions de sortie.|La proximité physique des deux directions~Elle ne démontre pas la fiabilité technique ou contractuelle.|Le seul prix par gigaoctet~Un coût unitaire ne prouve pas l’admissibilité du dispositif.
Le DG veut réduire une dépendance critique sans tout dupliquer. Quelle méthode convient ?|Analyser les modes de défaillance et barrières~Les protections doivent répondre aux causes et conséquences prioritaires.|Acheter un second exemplaire de chaque actif~La duplication uniforme peut conserver des causes communes.|Augmenter les franchises d’assurance~Le transfert financier ne réduit pas la dépendance opérationnelle.|Uniformiser tous les fournisseurs~L’uniformité peut augmenter l’exposition à une défaillance commune.
Un retour d’expérience propose vingt recommandations. Quel critère commande leur programme d’exécution ?|La réduction du risque avec dépendances et moyens~Les actions doivent être hiérarchisées et financées pour produire un effet réel.|Le nombre de recommandations par direction~Une répartition égale ne suit pas la criticité.|La facilité de rédaction des procédures~La clôture documentaire ne mesure pas la protection obtenue.|La date d’arrivée des rapports~L’ordre chronologique ne reflète pas nécessairement l’urgence.
Quelle hypothèse doit être testée avant de recourir à un fournisseur de secours ?|Sa capacité disponible dans une crise commune~Le même événement peut affecter d’autres clients et saturer ses moyens.|Sa notoriété au moment de la signature~La réputation ne prouve pas la disponibilité en situation de crise.|Le nombre de filiales figurant dans sa brochure~La taille affichée ne garantit pas les moyens contractuellement mobilisables.|Le montant de la remise initiale~Un prix favorable ne garantit pas le service de secours.
Une réorganisation de crise temporaire a été prolongée sans revue. Quel risque le DG doit-il traiter ?|Des pouvoirs et contrôles devenus inadaptés~Le dispositif exceptionnel doit rester justifié, borné et contrôlé.|La seule dénomination des nouvelles équipes~Le nom n’est pas le problème principal des pouvoirs exercés.|La hausse automatique de toutes les charges fixes~La prolongation ne démontre pas cet effet dans tous les cas.|La disparition nécessaire de la responsabilité du DG~Une organisation temporaire n’efface pas la responsabilité exécutive.
Cas fictif : trésorerie 2 millions, encaissements probables 0,8 million, paiements exigibles 3,4 millions. Quel besoin de financement ?|0,6 million~3,4 moins 2 moins 0,8 donne 0,6 million.|1,4 million~Ce montant ignore les encaissements probables.|2,6 millions~Ce calcul n’intègre pas correctement les liquidités initiales.|6,2 millions~La somme des flux n’est pas le besoin de financement.
Cas fictif : baisse de recettes de 20 % sur une base de 15 millions, coûts inchangés. Quelle baisse de résultat, hors autres effets ?|3 millions~La perte de recettes est de 15 × 20 %, soit 3 millions.|12 millions~C’est le nouveau niveau de recettes, pas la baisse du résultat.|0,2 million~Le taux n’est pas un montant en millions.|18 millions~Ce montant correspond à une hausse de 20 % des recettes initiales.
Cas fictif : dépense de continuité 0,45 million et ressources confirmées 0,3 million. Quel financement complémentaire faut-il sécuriser ?|0,15 million~0,45 moins 0,3 donne 0,15 million.|0,75 million~La somme des ressources et dépenses ne donne pas le complément.|0,3 million~C’est la ressource déjà confirmée.|0,45 million~C’est la dépense totale avant prise en compte des ressources.
Une assurance remboursera peut-être dans six mois une dépense à payer demain. Comment le DG l’intègre-t-il ?|Distinguer indemnité attendue et financement relais~Une créance éventuelle ne paie pas immédiatement la facture.|Compter l’indemnité comme trésorerie dès déclaration~La déclaration ne vaut ni acceptation ni versement.|Déduire la dépense du budget sans payer le fournisseur~La couverture supposée ne supprime pas l’obligation exigible.|Attendre l’assureur avant toute protection du service~La nécessité de protection doit être traitée avec des moyens adaptés.
Cas fictif : prêt de 1 million à 9 % annuel simple pendant huit mois. Quel intérêt hors frais ?|60 000~1 000 000 × 9 % × 8/12 donne 60 000.|90 000~C’est l’intérêt pour douze mois.|720 000~Ce calcul traite huit mois comme huit années.|7 500~C’est l’intérêt d’un seul mois.
Une mesure d’urgence coûte plus cher mais évite un arrêt critique. Comment le DG en prépare-t-il l’analyse financière ?|Coût complet, effet et options admissibles~La comparaison doit intégrer la protection obtenue et les modalités autorisées.|Prix unitaire le plus bas parmi toutes les offres~Une offre incapable de préserver le service n’est pas équivalente.|Montant maximal prévu par l’assurance~La couverture financière ne détermine pas seule le besoin.|Coût historique du dernier dépannage~Le contexte actuel et les solutions possibles peuvent différer.
Cas fictif : un programme de reprise comporte 40 actions dont 30 closes, mais les deux risques majeurs restent ouverts. Quel constat est juste ?|75 % de clôture ne prouve pas la maîtrise~Le taux brut ignore la criticité des actions restantes.|Le risque résiduel est réduit de 75 %~Le nombre d’actions ne mesure pas proportionnellement la réduction du risque.|Le financement restant est limité à 25 %~La valeur des actions n’est pas fournie.|La reprise totale peut être autorisée sur ce ratio~La décision dépend des critères opérationnels et risques résiduels.
Le DG présente une réserve budgétaire de crise sans distinguer déjà engagé et disponible. Que doit-il ajouter ?|Un état des engagements et du reste mobilisable~Le budget nominal ne décrit pas les moyens encore disponibles.|La moyenne des dépenses des trois années passées~Elle ne révèle pas les engagements de la crise actuelle.|La somme des montants assurés~Elle ne correspond pas aux liquidités immédiatement mobilisables.|Le nombre de factures classées par service~Le comptage ne mesure pas le solde réellement disponible.
Des preuves utiles à un incident cyber risquent d’être écrasées par une restauration. Quel arbitrage organise le DG ?|Préservation et reprise selon un plan compétent~Les spécialistes doivent concilier protection, conservation des preuves et continuité.|Restauration immédiate sans sauvegarde de l’état~Elle peut détruire les traces et empêcher l’analyse.|Conservation de toutes les machines sans service alternatif~La préservation doit aussi intégrer les exigences de continuité.|Analyse par le seul fournisseur soupçonné~L’indépendance et la maîtrise des accès seraient insuffisantes.
Pendant la crise, le DG reçoit des chiffres contradictoires sur les moyens disponibles. Que met-il en place ?|Une source de situation vérifiée et horodatée~Les arbitrages ont besoin d’un référentiel partagé avec limites explicites.|Une moyenne automatique de tous les chiffres~Des périmètres différents ne deviennent pas fiables par moyenne.|Le chiffre le plus favorable au maintien du trafic~L’objectif commercial ne sélectionne pas le fait exact.|Un gel des informations jusqu’à la fin de crise~Les décisions immédiates exigent une information mise à jour.
Un responsable clôt une action de crise car le fournisseur a livré. Quelle validation manque si l’action visait la disponibilité ?|Le fonctionnement effectif du service protégé~La livraison ne démontre pas l’effet opérationnel attendu.|La dernière facture du transporteur~Elle prouve un acheminement, pas le service rendu.|La nouvelle valeur de l’immobilisation~La valeur comptable ne valide pas l’efficacité.|Le nombre de destinataires du courriel de livraison~La diffusion n’est pas une preuve de fonctionnement.
L’astreinte fonctionne pendant la crise mais les équipes s’épuisent. Quel choix de DG protège la durée ?|Des rotations et renforts compatibles avec les qualifications~La continuité doit rester soutenable humainement et techniquement.|La reconduction du planning tant qu’aucune panne ne survient~L’absence de dommage ne prouve pas l’absence de risque de fatigue.|Une prime remplaçant les mesures de repos~Une compensation financière ne supprime pas la fatigue.|La substitution immédiate par tout agent disponible~La disponibilité ne vaut pas qualification requise.
Un site veut reprendre plus vite que le reste du réseau. Quel examen du DG doit précéder l’accord ?|Ses prérequis propres et interfaces communes~Une capacité locale ne suffit pas si une dépendance réseau reste indisponible.|La seule confirmation du directeur commercial local~Elle ne démontre pas les conditions opérationnelles de reprise.|Le rang du site dans les recettes annuelles~La contribution financière ne valide pas la sécurité.|L’alignement automatique sur la date du dernier site~Une reprise uniforme n’est pas toujours nécessaire si les interfaces sont maîtrisées.
Un traitement d’urgence a contourné un contrôle habituel. Quelle suite organise le DG ?|Vérifier la base, tracer et contrôler a posteriori~Les dérogations admissibles doivent rester justifiées et contrôlées.|Maintenir le contournement puisque le service a repris~Un résultat favorable ne valide pas tout moyen employé.|Effacer la trace pour éviter une mauvaise interprétation~La perte de traçabilité empêche le contrôle et le retour d’expérience.|Considérer la crise comme habilitation générale~Une crise ne crée pas automatiquement tous les pouvoirs de décision.
La crise est stabilisée. Quand peut-on clore le dispositif exceptionnel ?|Quand les critères de sortie et relais sont vérifiés~Le retour au mode normal nécessite responsabilités, risques résiduels et suivi définis.|Dès la première journée sans appel d’urgence~Une accalmie ne garantit pas la disparition des fragilités.|Dès le paiement des factures principales~Le règlement financier ne prouve pas la stabilisation opérationnelle.|À la date annoncée au début de crise~Le calendrier doit être confronté à l’état réel et aux critères de sortie.
Un membre du conseil demande directement à une équipe de changer le plan de reprise. Que fait le DG ?|Rétablir le circuit de décision compétent~Les instructions doivent respecter gouvernance, délégations et chaîne habilitée.|Appliquer l’ordre individuel comme délibération du conseil~Une demande personnelle ne vaut pas décision collégiale régulière.|Laisser l’équipe choisir entre les deux ordres~Le conflit d’autorité doit être résolu par la direction.|Interrompre tout compte rendu au conseil~La clarification des rôles ne supprime pas le devoir d’information utile.
Une communication publique minimise un risque encore non traité. Quelle version valide le DG ?|Faits confirmés, limites et mesures en cours~L’information doit être fidèle sans exposer inutilement des détails sensibles.|Absence de risque affirmée pour éviter l’inquiétude~Une affirmation non étayée masque l’exposition réelle.|Liste exhaustive des vulnérabilités techniques~La transparence doit aussi protéger les informations sensibles.|Silence jusqu’à disparition de toute incertitude~Une information utile peut être nécessaire avant une certitude totale.
Le conseil demande qui doit exécuter les résolutions de reprise. Quelle réponse du DG est exacte ?|La DG avec responsables, moyens et compte rendu~Le conseil décide dans ses compétences ; la direction organise l’exécution.|Le PCA en donnant les ordres techniques quotidiens~La présidence du conseil ne se confond pas avec la gestion opérationnelle.|Le comité d’audit en gérant les équipes de site~Le contrôle indépendant ne remplace pas la direction des opérations.|Le régulateur en planifiant les interventions internes~La surveillance réglementaire ne constitue pas la gestion du prestataire.
Cas fictif : fausse information publique, panne réelle et trésorerie limitée. Quelle séquence du DG est la plus robuste ?|Protéger le service puis informer sur les faits vérifiés~La réponse combine mesures opérationnelles, financement et information fiable.|Démentir toute panne pour neutraliser la rumeur~La panne réelle rend ce démenti inexact.|Régler d’abord la communication avant de mobiliser les équipes~La protection immédiate ne doit pas attendre le traitement médiatique.|Publier toutes les hypothèses techniques disponibles~Les hypothèses non vérifiées peuvent amplifier la confusion.
Cas fictif : le même composant tombe en panne sur un site et équipe quatre autres plateformes. Quelle décision prend le DG ?|Évaluer l’exposition commune et protéger les sites~Le retour d’expérience doit rechercher le mode commun sans attendre d’autres incidents.|Remplacer tous les composants sans vérifier la cause~Une intervention identique peut être inutile ou créer de nouveaux risques.|Réparer le premier site puis attendre les prochains défauts~L’exposition connue des autres sites reste sans évaluation.|Transférer les composants du site le moins rentable~La rentabilité seule ne définit pas une allocation sûre des moyens.
Cas fictif : la crise exige une dépense hors délégation et une protection immédiate. Comment le DG agit-il ?|Protection dans ses pouvoirs et saisine rapide~Il doit combiner mesures conservatoires autorisées et arbitrage compétent documenté.|Signature totale puis régularisation sans information~L’urgence ne crée pas automatiquement le pouvoir manquant.|Attente passive de la prochaine séance ordinaire~Les mesures conservatoires et la saisine urgente restent à organiser.|Fractionnement de la dépense entre plusieurs sites~Le fractionnement contourne le problème de compétence.
Cas fictif : service rétabli, fatigue élevée, cause commune non corrigée. Quel message de DG au conseil est fidèle ?|Reprise acquise avec risques résiduels et plan~La reprise doit être distinguée de la maîtrise durable des causes.|Crise entièrement close puisque le trafic circule~Le service rétabli ne supprime pas fatigue et vulnérabilité commune.|Échec total malgré la reprise du service~Ce jugement efface le résultat réel et n’explicite pas les limites.|Situation normale dès accord de l’assureur~La position financière de l’assureur ne valide pas l’état opérationnel.
`,[
['A','Expliquez la différence entre rétablir le service RVA après une crise et maîtriser durablement le risque qui l’a interrompu.','Le rétablissement valide un niveau de service sous des conditions définies ; il peut s’appuyer sur des mesures temporaires. La maîtrise durable traite les causes, dépendances, compétences et barrières, avec preuve d’efficacité. Le DG distingue les deux dans ses décisions et rapports, attribue le suivi des risques résiduels et fixe les critères de sortie du mode exceptionnel.','Reprise versus maîtrise durable','Risques résiduels','Critères et responsables'],
['B','Une crise fictive impose de reprogrammer le portefeuille RVA. Comment recommandez-vous de répartir les ressources entre continuité, maintenance et croissance ?','Identifier fonctions critiques, obligations et engagements, puis comparer les effets futurs des projets et leurs dépendances. Protéger la continuité et traiter les expositions majeures, chiffrer le rattrapage de maintenance et rephaser les projets moins prioritaires. Examiner coûts de sortie et financements fléchés. Proposer des arbitrages documentés au niveau compétent puis exécuter avec responsables et jalons.','Priorités et dépendances','Coûts futurs et financement','Arbitrage et exécution'],
['C','Cas fictif : trésorerie 1,5 million ; encaissements confirmés 0,7 million ; paiement critique 1,8 million ; autres dettes exigibles 1 million. Calculez le besoin global et les limites d’une simple priorité au paiement critique.','Les ressources de 2,2 millions face à 2,8 millions exigibles créent un besoin de 0,6 million. Payer 1,8 million laisse 0,4 million pour 1 million d’autres dettes. La priorité technique ne supprime pas ces obligations : vérifier leurs conséquences, négocier des échéances et sécuriser des ressources autorisées, avec une prévision datée et des scénarios de retard.','Besoin global 0,6 million','Reste 0,4 pour 1 million','Obligations et financement'],
['C','Cas fictif : dette de 200 000 USD, cours de 2 400 puis 2 700 unités locales. Calculez l’écart de paiement et proposez le suivi de DG avec recettes principalement locales.','La dette passe de 480 à 540 millions d’unités locales, soit 60 millions supplémentaires. Cartographier les échéances et expositions, tester les cours et retards de recettes, identifier les ressources en devises ou mécanismes de couverture autorisés. Adapter le plan de trésorerie et les arbitrages compétents ; distinguer montant dû, écarts comptables et liquidité effectivement mobilisable.','480 puis 540 millions','Surcoût 60 millions','Échéancier et réponses autorisées'],
['D','Une crise cyber fictive touche un système RVA alors que la continuité exige une restauration rapide. Qu’organisez-vous comme DG ?','Mobiliser les spécialistes et la conduite d’incident, protéger les fonctions critiques et maîtriser les accès. Préserver les preuves de façon compatible avec la reprise, vérifier les sauvegardes et dépendances, puis restaurer dans un environnement contrôlé selon critères d’acceptation. Coordonner les informations et signalements applicables, affecter les moyens et suivre risques résiduels et causes sans laisser le fournisseur seul arbitre.','Protection et expertise','Preuves et restauration contrôlée','Coordination et suivi'],
['D','Après un incident RVA fictif, plusieurs plateformes utilisent le même composant. Comment dirigez-vous un retour d’expérience multisites proportionné ?','Préserver les faits et rechercher les modes de défaillance communs avec les experts. Évaluer l’exposition de chaque site selon configuration, environnement, usage et barrières. Décider de protections proportionnées, prioriser les interventions et organiser ressources et fenêtres d’exploitation. Tester les corrections et diffuser les enseignements avec responsables et échéances, sans copier une réparation non validée sur tous les sites.','Analyse des causes communes','Évaluation par site','Actions et essais proportionnés'],
['D','L’astreinte de crise RVA fictive dure depuis plusieurs semaines. Préparez le retour à une organisation soutenable.','Réévaluer la situation, les fonctions prioritaires, fatigue, qualifications et risques résiduels. Organiser rotations, renforts et suppléances avec ressources adaptées. Définir critères de sortie, pouvoirs transitoires et relais vers les responsables ordinaires. Contrôler les mesures exceptionnelles, documenter les décisions et maintenir un suivi des causes non traitées. Informer le conseil de la reprise, des limites et du plan de stabilisation.','Fatigue et qualifications','Critères et relais','Contrôle et stabilisation'],
['E','Le PCA RVA vous demande pendant une crise une décision opérationnelle incompatible avec l’avis des responsables habilités. Comment agissez-vous comme DG ?','Clarifier la demande et présenter les faits, risques, limites et compétences applicables. Maintenir les protections nécessaires et les décisions techniques dans la chaîne habilitée. Préparer des options et saisir l’organe compétent si l’arbitrage dépasse la délégation, en traçant les échanges. Ne pas confondre demande individuelle, résolution régulière et habilitation opérationnelle ; continuer à rendre compte fidèlement.','Rôles et faits clarifiés','Protection et chaîne habilitée','Escalade et traçabilité'],
['E','Une dépense urgente RVA fictive a été autorisée avec une procédure exceptionnelle. Quels contrôles organisez-vous comme DG après stabilisation ?','Vérifier le fondement de l’exception, les pouvoirs, la réalité du besoin, le service fait, les prix et paiements. Préserver les pièces, documenter les décisions et examiner conflits d’intérêts et éventuels écarts par les fonctions compétentes. Rendre compte sans effacer les irrégularités éventuelles, corriger les contrôles et borner la fin des mesures exceptionnelles pour éviter leur pérennisation.','Base et pouvoirs','Service fait et traçabilité','Contrôle et fin de l’exception'],
['F','Cas fictif de synthèse : panne commune sur deux plateformes RVA, dette en devises, équipes fatiguées et pression du conseil pour une reprise intégrale sous quarante-huit heures. Présentez votre décision de DG.','Faire établir la capacité sûre et activer une continuité proportionnée par les responsables habilités. Mobiliser renforts qualifiés et réparation, protéger repos et ressources critiques. Chiffrer trésorerie et change, sécuriser les ressources autorisées et soumettre les arbitrages hors délégation. Proposer une reprise graduée selon essais et critères vérifiables ; informer le conseil des limites, délais conditionnels, responsables et risques résiduels.','Continuité et capacité sûre','Ressources humaines et financement','Reprise vérifiée et compte rendu'],
]);

export function buildRvaDgExams(){
  return packs.map(({n,title,mcq,written})=>{
    const lines=mcq.trim().split('\n').filter(Boolean);
    if(lines.length!==40||written.length!==10)throw new Error(`RVA DG ${n}: ${lines.length} QCM / ${written.length} écrits`);
    const positions=Array.from({length:40},(_,i)=>i%4);let seed=2309+n*71;
    for(let i=39;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[positions[i],positions[j]]=[positions[j],positions[i]];}
    const serial={};
    const questions=lines.map((line,i)=>{
      const [prompt,...entries]=line.split('|');
      if(entries.length!==4)throw new Error(`Quatre assertions requises : ${prompt}`);
      const parsed=entries.map(entry=>{const [text,reason,...extra]=entry.split('~');if(!text||!reason||extra.length)throw new Error(prompt);return {text,reason};});
      const correct=parsed[0],answer=positions[i];
      while(parsed.indexOf(correct)!==answer)parsed.push(parsed.shift());
      let limit=0;const section=sections.find((_,j)=>(limit+=counts[j])>i);
      serial[section]=(serial[section]||0)+1;
      return {id:`rvaDG${n}-${section}-M${String(serial[section]).padStart(2,'0')}`,section,type:'mcq',prompt,choices:parsed.map(x=>x.text),answer,
        explanation:correct.reason,choiceExplanations:parsed.map(x=>x.reason),discriminant:correct.reason,
        commentRequired:[10,20,28,37].includes(i),sources,lastVerified:'2026-11-05'};
    });
    const shorts={};
    for(const [section,prompt,modelAnswer,...essentials]of written){
      shorts[section]=(shorts[section]||0)+1;
      questions.push({id:`rvaDG${n}-${section}-S${shorts[section]}`,section,type:'short',prompt,modelAnswer,essentials,
        instruction:'Répondez en tant que directeur général de la RVA : décidez, organisez l’exécution, affectez les responsabilités et les moyens, puis rendez compte. Respectez les compétences du conseil, de l’AAC et des intervenants habilités. Justifiez les calculs utiles.',
        minWords:60,maxWords:100,commentRequired:false,sources,lastVerified:'2026-11-05'});
    }
    refineDgChallenges(questions);
    return {id:`rva-${n}`,company:'RVA',role:'DG',bankVersion:RVA_DG_VERSION,title:`RVA DG — ${n}. ${title}`,durationMinutes:60,
      notice:'Préparation au poste de directeur général. Questions originales, non officielles. Tous les cas, chiffres, budgets, incidents et hypothèses sont fictifs. Les sources institutionnelles documentent le contexte ; les décisions de gestion proposées sont pédagogiques et ne constituent pas des procédures opérationnelles aéronautiques.',questions};
  });
}
